__sources["http"] = function(...)
do end
-- HTTP with retries, built on ComputerCraft's `http.request`.
--
-- CC's request is a blocking read of the whole body, so there is no incremental
-- streaming here. Requests that ask for `stream = true` are buffered and then
-- reassembled from SSE frames by the LLM client.

local json = require("json")
local util = require("util")

local M = {}

M.DEFAULT_TIMEOUT = 60
M.RETRYABLE = { [408] = true, [409] = true, [429] = true, [500] = true, [502] = true, [503] = true, [504] = true, [529] = true }
M.MAX_ATTEMPTS = 3
M.BASE_DELAY = 1
M.MAX_DELAY = 16

--- Split a `data:` payload stream into its individual SSE frame strings.
function M.parseSse(body)
  local frames = {}
  for frame in (body or ""):gmatch("data:%s*([^\n]*)\n") do
    frame = frame:gsub("\r$", "")
    if frame ~= "" and frame ~= "[DONE]" then
      frames[#frames + 1] = frame
    end
  end
  return frames
end

--- Read a CC handle to completion, capping the result at `maxBytes`.
local function readHandle(handle, maxBytes)
  local body = handle.readAll and handle.readAll() or handle.read("*a")
  handle.close()
  if not maxBytes or #body <= maxBytes then
    return body or ""
  end
  return body:sub(1, maxBytes)
end

--- Case-insensitive header lookup; CC normalises header names but not reliably.
local function lookup(headers, name)
  if not headers then
    return nil
  end
  local direct = headers[name]
  if direct then
    return direct
  end
  local lowered = name:lower()
  for key, value in pairs(headers) do
    if key:lower() == lowered then
      return value
    end
  end
  return nil
end

--- Seconds to wait before retrying, honouring Retry-After when the server sent it.
local function backoff(attempt, headers)
  local retryAfter = lookup(headers, "retry-after-ms") or lookup(headers, "retry-after")
  if retryAfter then
    local ms = tonumber(retryAfter)
    if ms then
      return math.min(60, ms / 1000)
    end
    local date = tonumber(retryAfter)
    if date and date > os.time() then
      return math.min(60, date - os.time())
    end
  end
  return math.min(M.MAX_DELAY, M.BASE_DELAY * 2 ^ (attempt - 1)) * (0.75 + math.random() * 0.5)
end

--- Perform a request, retrying 429 and 5xx responses.
--
-- Returns `response` on success, or `nil, message` on failure. A non-2xx status
-- is returned as a normal response so callers can read the provider's error
-- body; only transport failures and exhausted retries become errors.
function M.request(url, options)
  options = options or {}
  local attempts = options.attempts or M.MAX_ATTEMPTS
  local lastError = "no attempt was made"

  for attempt = 1, attempts do
    local ok, handle = pcall(http.request, url, {
      method = options.method or "GET",
      headers = options.headers,
      body = options.body,
      timeout = options.timeout or M.DEFAULT_TIMEOUT,
    })

    if ok and handle then
      local status = handle.getResponseCode and handle.getResponseCode() or 200
      local headers = handle.getResponseHeaders and handle.getResponseHeaders() or {}
      local response = { status = status, headers = headers, body = readHandle(handle, options.maxBytes) }
      if not (M.RETRYABLE[status] and attempt < attempts) then
        return response
      end
      lastError = "HTTP " .. status
      if attempt < attempts then
        util.sleep(backoff(attempt, headers))
      end
    else
      lastError = "could not reach " .. url .. " (" .. tostring(handle) .. ")"
      if attempt < attempts then
        util.sleep(backoff(attempt, nil))
      end
    end
  end

  return nil, lastError
end

--- Best-effort extraction of a human readable message from a failed response.
function M.errorMessage(response)
  local body = response.body or ""
  local decoded = json.decode(body)
  if type(decoded) == "table" then
    local message = decoded.error
    if type(message) == "table" then
      message = message.message
    end
    if type(message) == "string" and message ~= "" then
      return "HTTP " .. response.status .. ": " .. message
    end
  end
  local trimmed = util.trim(body)
  if trimmed == "" then
    trimmed = "(empty response body)"
  end
  if #trimmed > 400 then
    trimmed = trimmed:sub(1, 400) .. "..."
  end
  return "HTTP " .. response.status .. ": " .. trimmed
end

--- POST a JSON body. Returns a response table with `data` holding the decode.
--
-- `options.decode = false` leaves `data` unset, for callers that expect an
-- event stream rather than a JSON document.
function M.postJson(url, payload, options)
  options = options or {}
  local response, err = M.request(url, {
    method = "POST",
    headers = options.headers,
    body = options.raw or json.encode(payload),
    timeout = options.timeout,
    attempts = options.attempts,
    maxBytes = options.maxBytes,
  })
  if not response then
    return nil, err
  end
  if response.status < 200 or response.status >= 300 then
    return nil, M.errorMessage(response)
  end

  if options.decode == false then
    return response
  end
  response.data = json.decode(response.body or "")
  if not response.data then
    return nil, "could not parse the response as JSON: " .. tostring(response.body):sub(1, 200)
  end
  return response
end

return M

end

-- src/environment.lua
__sources["environment"] = function(...)
do end
-- ComputerCraft environment access.
--
-- Every CC API the project touches goes through this module so the rest of the
-- code has no direct `fs`/`shell`/`http` references. The test harness swaps in a
-- mock with the same surface, which is how the agent loop is exercised without
-- a Minecraft client.

local M = {}

M.isCC = type(shell) == "table" and type(fs) == "table"

-- Defined here rather than required from `util` so the environment layer stays
-- the one module that depends on nothing else.
local function startswith(s, prefix)
  return s:sub(1, #prefix) == prefix
end

local function endswith(s, suffix)
  return suffix == "" or s:sub(-#suffix) == suffix
end

M.startswith, M.endswith = startswith, endswith

function M.cwd()
  if not M.isCC then
    return (os.getenv and os.getenv("PWD")) or "/"
  end
  return shell.dir()
end

function M.combine(...)
  if M.isCC then
    return fs.combine(...)
  end
  local parts = { ... }
  local out = "/"
  for _, part in ipairs(parts) do
    if part == nil or part == "" then
      -- skip
    elseif out == "/" then
      out = "/" .. tostring(part)
    else
      out = out .. "/" .. tostring(part)
    end
  end
  return (out:gsub("//+", "/"))
end

function M.dirname(path)
  if M.isCC then
    return fs.getDir(path)
  end
  local dir = path:match("^(.*)/[^/]*$")
  if not dir or dir == "" then
    return "/"
  end
  return dir
end

function M.basename(path)
  if M.isCC then
    return fs.getName(path)
  end
  return path:match("([^/]*)$") or path
end

function M.isAbsolute(path)
  return M.startswith(path or "", "/")
end

--- Resolve `path` against `base` and normalise "." and ".." segments.
function M.resolve(path, base)
  local absolute = M.isAbsolute(path) and path or M.combine(base or M.cwd(), path)
  local parts = {}
  for segment in absolute:gmatch("[^/]+") do
    if segment == "." then
      -- skip
    elseif segment == ".." then
      parts[#parts] = nil
    else
      parts[#parts + 1] = segment
    end
  end
  return "/" .. table.concat(parts, "/")
end

--- True when `path` is `root` or lives inside it.
function M.contains(root, path)
  if root == path then
    return true
  end
  if M.endswith(root, "/") then
    return M.startswith(path, root)
  end
  return M.startswith(path, root .. "/")
end

function M.exists(path)
  if M.isCC then
    return fs.exists(path)
  end
  local handle = io.open(path, "r")
  if handle then
    handle:close()
    return true
  end
  -- Directories are not readable as files, so fall back to a probe.
  local pipe = io.popen("test -e " .. M.quote(path) .. " && echo yes")
  if not pipe then
    return false
  end
  local out = pipe:read("*a")
  pipe:close()
  return out == "yes"
end

function M.isDir(path)
  if M.isCC then
    return fs.isDir(path)
  end
  local pipe = io.popen("test -d " .. M.quote(path) .. " && echo yes")
  if not pipe then
    return false
  end
  local out = pipe:read("*a")
  pipe:close()
  return out == "yes"
end

function M.size(path)
  if M.isCC then
    return fs.getSize(path)
  end
  local handle = io.open(path, "rb")
  if not handle then
    return 0
  end
  local size = handle:seek("end")
  handle:close()
  return size
end

function M.modified(path)
  if M.isCC then
    return fs.attributes(path, "modification") or 0
  end
  local pipe = io.popen("date -r " .. M.quote(path) .. " +%s 2>/dev/null")
  if not pipe then
    return 0
  end
  local out = pipe:read("*a")
  pipe:close()
  return tonumber(out) or 0
end

function M.mkdir(path)
  if M.isCC then
    return fs.makeDir(path)
  end
  return os.execute("mkdir -p " .. M.quote(path))
end

--- Create `path` and every missing parent, ignoring directories that already exist.
function M.mkdirs(path)
  local current = "/"
  for segment in path:gmatch("[^/]+") do
    current = current .. segment
    if not M.isDir(current) then
      M.mkdir(current)
    end
    current = current .. "/"
  end
  return M.isDir(path)
end

function M.read(path)
  if M.isCC then
    local handle = fs.open(path, "r")
    if not handle then
      return nil
    end
    local content = handle.readAll()
    handle.close()
    return content
  end
  local handle = io.open(path, "rb")
  if not handle then
    return nil
  end
  local content = handle:read("*a")
  handle:close()
  return content
end

--- Read at most `limit` bytes, reporting whether the file was cut short.
function M.readLimited(path, limit)
  local size = M.size(path)
  if limit and size > limit then
    if M.isCC then
      local handle = fs.open(path, "r")
      if not handle then
        return nil
      end
      local chunk = handle.read(limit) or ""
      handle.close()
      return chunk, true
    end
    local handle = io.open(path, "rb")
    if not handle then
      return nil
    end
    local chunk = handle:read(limit) or ""
    handle:close()
    return chunk, true
  end
  return M.read(path), false
end

function M.write(path, content)
  if M.isCC then
    local handle = fs.open(path, "w")
    if not handle then
      return false
    end
    handle.write(content)
    handle.close()
    return true
  end
  local handle = io.open(path, "wb")
  if not handle then
    return false
  end
  handle:write(content)
  handle:close()
  return true
end

function M.append(path, content)
  if M.isCC then
    local handle = fs.open(path, "a")
    if not handle then
      return false
    end
    handle.write(content)
    handle.close()
    return true
  end
  local handle = io.open(path, "ab")
  if not handle then
    return false
  end
  handle:write(content)
  handle:close()
  return true
end

function M.remove(path)
  if M.isCC then
    return fs.delete(path)
  end
  return os.remove(path)
end

function M.rename(from, to)
  if fs and fs.posix then
    local ok = fs.posix.rename(from, to)
    if ok then
      return true
    end
  end
  if not os.rename(from, to) then
    return false
  end
  return true
end

--- Entry names in a directory, sorted, excluding "." and "..".
function M.listDir(path)
  local names = {}
  if M.isCC then
    for _, name in ipairs(fs.dir(path)) do
      names[#names + 1] = name
    end
  else
    local pipe = io.popen("ls -A " .. M.quote(path) .. " 2>/dev/null")
    if pipe then
      for name in pipe:lines() do
        names[#names + 1] = name
      end
      pipe:close()
    end
  end
  table.sort(names)
  return names
end

--- Walk `path` depth-first, calling `onFile` and `onDir` with absolute paths.
-- `onDir` returning false skips that subtree.
function M.walk(path, options)
  local onFile = options.onFile or function() end
  local onDir = options.onDir or function() end
  local includeHidden = options.includeHidden
  local maxDepth = options.maxDepth or 32

  local function visit(dir, depth)
    if depth > maxDepth or not M.isDir(dir) then
      return
    end
    for _, name in ipairs(M.listDir(dir)) do
      if includeHidden or not M.startswith(name, ".") then
        local full = dir .. (dir == "/" and "" or "/") .. name
        if M.isDir(full) then
          if onDir(full, name) ~= false then
            visit(full, depth + 1)
          end
        else
          onFile(full, name)
        end
      end
    end
  end

  visit(path, 1)
end

--- Single-quote a value for the ComputerCraft shell.
function M.quote(value)
  return "'" .. tostring(value):gsub("'", "'\\''") .. "'"
end

function M.now()
  if os.date then
    return os.date("%c")
  end
  return "unknown"
end

function M.today()
  if os.date then
    return os.date("%Y-%m-%d")
  end
  return "unknown"
end

function M.computerLabel()
  if M.isCC and os.getComputerLabel then
    return os.getComputerLabel() or "computer"
  end
  return "host"
end

--- A screen presenting the same methods whether it is a monitor or a terminal.
--
-- Monitors and terminals are nearly the same API, but neither is a superset of
-- the other, and the REPL should not have to care which one it got.
local function adapt(screen)
  -- ComputerCraft calls these with a dot — `term.write(text)`, not
  -- `term:write(text)` — so the screen must not be passed back in.
  local function call(name, ...)
    local method = screen[name]
    if not method then
      return nil
    end
    return method(...)
  end
  return {
    raw = screen,
    isMonitor = screen ~= term,
    write = function(text) return call("write", text) end,
    readLine = function() return call("readLine") end,
    clear = function() return call("clear") end,
    scroll = function() return call("scroll") end,
    setCursorBlink = function(state) return call("setCursorBlink", state) end,
    setCursorPos = function(x, y) return call("setCursorPos", x, y) end,
    setTextColor = function(colour) return call("setTextColor", colour) end,
    getCursorPos = function() return call("getCursorPos") end,
    getSize = function() return call("getSize") end,
  }
end

--- The best available screen, or nil when there is neither a monitor nor a
--- terminal. Monitors are preferred, so a multi-computer setup prints to the
--- monitor rather than to the computer nobody is looking at.
function M.terminal()
  if peripheral and peripheral.find then
    for _, name in ipairs({ "left", "right", "monitor_1", "monitor_2", "monitor_3" }) do
      local monitor = peripheral.find(name)
      if monitor then
        return adapt(monitor)
      end
    end
  end
  if term then
    return adapt(term)
  end
  return nil
end

return M

end

-- src/config.lua
__sources["config"] = function(...)
do end
-- Configuration loading.
--
-- Precedence, lowest to highest: built-in defaults, `opencode.json` in the
-- working directory, `/opencode.json`, then runtime overrides passed by the CLI.

local json = require("json")
local util = require("util")
local env = require("environment")

local M = {}

M.DEFAULT_MODEL = "opencode/gpt-5"
M.DEFAULT_SMALL_MODEL = "opencode/gpt-5-mini"

M.DEFAULTS = {
  model = M.DEFAULT_MODEL,
  small_model = M.DEFAULT_SMALL_MODEL,
  tool_output = { max_lines = 2000, max_bytes = 50 * 1024 },
  compaction = { auto = true, reserved = 20 * 1024 },
  -- Name a session from its first question when it is saved. Set to false to
  -- skip the extra request.
  title = true,
  agent = {
    build = { steps = 25 },
    general = { steps = 15 },
    plan = { steps = 25 },
  },
  permission = {
    { permission = "*", pattern = "*", action = "allow" },
    { permission = "doom_loop", pattern = "*", action = "ask" },
    { permission = "external_directory", pattern = "*", action = "ask" },
    { permission = "read", pattern = "*.env", action = "ask" },
    { permission = "read", pattern = "*.env.*", action = "ask" },
    { permission = "read", pattern = "*.env.example", action = "allow" },
  },
}

--- Built-in OpenAI-compatible providers, mirroring opencode's profile table.
-- `env` lists the variable names the credential is read from in `config.env`,
-- which stands in for a real process environment.
M.PROFILES = {
  opencode = { name = "opencode zen", base = "https://models.opencode.ai/api/v1", env = { "OPENCODE_API_KEY" }, apiKey = "public" },
  openai = { name = "OpenAI", base = "https://api.openai.com/v1", env = { "OPENAI_API_KEY" } },
  openrouter = { name = "OpenRouter", base = "https://openrouter.ai/api/v1", env = { "OPENROUTER_API_KEY" } },
  groq = { name = "Groq", base = "https://api.groq.com/openai/v1", env = { "GROQ_API_KEY" } },
  cerebras = { name = "Cerebras", base = "https://api.cerebras.ai/v1", env = { "CEREBRAS_API_KEY" } },
  deepinfra = { name = "DeepInfra", base = "https://api.deepinfra.com/v1/openai", env = { "DEEPINFRA_API_KEY" } },
  deepseek = { name = "DeepSeek", base = "https://api.deepseek.com/v1", env = { "DEEPSEEK_API_KEY" } },
  fireworks = { name = "Fireworks", base = "https://api.fireworks.ai/inference/v1", env = { "FIREWORKS_API_KEY" } },
  togetherai = { name = "Together AI", base = "https://api.together.xyz/v1", env = { "TOGETHER_API_KEY" } },
  xai = { name = "xAI", base = "https://api.x.ai/v1", env = { "XAI_API_KEY" } },
  ollama = { name = "Ollama", base = "http://localhost:11434/v1", env = { "OLLAMA_API_KEY" }, apiKey = "ollama" },
  lmstudio = { name = "LM Studio", base = "http://localhost:1234/v1", env = { "LMSTUDIO_API_KEY" }, apiKey = "lmstudio" },
}

--- Search paths for opencode.json, relative entries resolved against the cwd.
M.CONFIG_PATHS = { "opencode.json", "/opencode.json", "/.opencode/opencode.json" }

local function readConfigFile(path)
  local content = env.read(path)
  if not content then
    return nil
  end
  return json.decode(content)
end

local function merge(target, source)
  for key, value in pairs(source) do
    if type(value) == "table" and type(target[key]) == "table" then
      merge(target[key], value)
    else
      target[key] = value
    end
  end
  return target
end

local function readAll(cwd)
  local config = {}
  for _, candidate in ipairs(M.CONFIG_PATHS) do
    local path = util.startswith(candidate, "/") and candidate or env.combine(cwd, candidate)
    local parsed = readConfigFile(path)
    if type(parsed) == "table" then
      merge(config, parsed)
      config.__source = config.__source or path
    end
  end
  return config
end

--- Load configuration, applying `overrides` from the command line on top.
function M.load(cwd, overrides)
  local config = merge(util.deepCopy(M.DEFAULTS), readAll(cwd or env.cwd()))
  if overrides then
    merge(config, overrides)
  end
  config.cwd = cwd or env.cwd()
  return config
end

--- Read an API key from the config, a key file, or `config.env`.
function M.apiKey(config, provider)
  local options = provider.options or {}
  if type(options.apiKey) == "string" and options.apiKey ~= "" then
    return options.apiKey
  end
  if type(options.apiKeyFile) == "string" and options.apiKeyFile ~= "" then
    local path = util.startswith(options.apiKeyFile, "/") and options.apiKeyFile
      or env.combine(config.cwd, options.apiKeyFile)
    local content = env.read(path)
    if content then
      return util.trim(content)
    end
  end
  for _, name in ipairs(provider.env or {}) do
    local value = (config.env or {})[name]
    if type(value) == "string" and value ~= "" then
      return value
    end
  end
  -- Profiles that need no real credential (a public key, or a local server that
  -- ignores the header) carry one. It is the last resort so a supplied
  -- credential always wins.
  if type(provider.apiKey) == "string" and provider.apiKey ~= "" then
    return provider.apiKey
  end
  return nil
end

function M.toolOutputLimits(config)
  local options = config.tool_output or {}
  return {
    max_lines = options.max_lines or M.DEFAULTS.tool_output.max_lines,
    max_bytes = options.max_bytes or M.DEFAULTS.tool_output.max_bytes,
  }
end

return M

end

-- src/provider.lua
__sources["provider"] = function(...)
do end
-- Provider and model resolution.
--
-- Model ids are `provider/model`, split on the FIRST slash only, so nested ids
-- like `openrouter/anthropic/claude-sonnet-4` resolve to provider `openrouter`
-- with model id `anthropic/claude-sonnet-4`.

local config = require("config")
local util = require("util")

local M = {}

M.DEFAULT_LIMIT = { context = 128 * 1024, output = 8 * 1024 }

M.SSE_PATH = "/chat/completions"

--- Re-exported so callers only need this module to resolve a credential.
M.apiKey = config.apiKey

--- Split a model string into its provider and model halves.
function M.parseModel(model)
  local slash = model:find("/", 1, true)
  if not slash then
    return model, ""
  end
  return model:sub(1, slash - 1), model:sub(slash + 1)
end

--- Merge a built-in profile with any user override of the same provider id.
local function buildProfile(id, override)
  local profile = config.PROFILES[id] or {}
  local merged = util.deepCopy(profile)
  merged.id = id
  merged.base = (override and override.api) or profile.base
  merged.name = (override and override.name) or profile.name or id
  merged.env = (override and override.env) or profile.env
  merged.apiKey = profile.apiKey
  if override and override.options then
    merged.options = util.deepCopy(override.options)
  end
  return merged
end

--- All known providers: built-in profiles overlaid with `config.provider`.
function M.list(configValue)
  local providers = {}
  for id, _ in pairs(config.PROFILES) do
    providers[id] = buildProfile(id, (configValue.provider or {})[id])
  end
  for id, override in pairs(configValue.provider or {}) do
    providers[id] = buildProfile(id, override)
  end
  return providers
end

--- Resolved provider entry: base url, credential, and model metadata.
function M.get(configValue, providerID)
  local providers = M.list(configValue)
  local provider = providers[providerID]
  if not provider then
    return nil, "Unknown provider '" .. providerID .. "'. Add it under \"provider\" in opencode.json."
  end
  if not provider.base then
    return nil, "Provider '" .. providerID .. "' has no baseURL. Set options.baseURL in opencode.json."
  end
  local key = config.apiKey(configValue, provider)
  if not key then
    local names = table.concat(provider.env or {}, ", ")
    return nil, "No API key for provider '" .. providerID .. "'. Set options.apiKey, options.apiKeyFile, or env."
      .. (names ~= "" and (" (" .. names .. ")") or "")
  end
  provider.apiKeyResolved = key
  return provider
end

local function mergeOptions(providerOptions, modelOptions)
  local out = util.deepCopy(providerOptions or {})
  for key, value in pairs(modelOptions or {}) do
    out[key] = value
  end
  return out
end

--- Metadata for one model within a provider, merged with the provider defaults.
function M.model(configValue, providerID, modelID)
  local provider = M.get(configValue, providerID)
  if not provider then
    return nil, select(2, M.get(configValue, providerID))
  end
  local override = ((configValue.provider or {})[providerID] or {}).models or {}
  local entry = override[modelID] or {}
  return {
    providerID = providerID,
    id = modelID,
    name = entry.name or modelID,
    base = provider.base,
    apiKey = provider.apiKeyResolved,
    api = provider.api,
    limit = entry.limit or M.DEFAULT_LIMIT,
    options = mergeOptions(provider.options, entry.options),
    headers = entry.headers or (provider.options or {}).headers,
  }
end

--- Resolve a full `provider/model` string, including default-model selection.
function M.resolve(configValue, modelString)
  if not modelString or modelString == "" then
    return nil, "No model configured. Set \"model\" in opencode.json, e.g. \"openrouter/anthropic/claude-sonnet-4\"."
  end
  local providerID, modelID = M.parseModel(modelString)
  if modelID == "" then
    return nil, "Model '" .. modelString .. "' has no model part. Use the form provider/model."
  end
  local model, err = M.model(configValue, providerID, modelID)
  if not model then
    return nil, err
  end
  return model
end

--- Full request url for a model: base with trailing slashes trimmed, plus the path.
function M.url(model, path)
  return model.base:gsub("/+$", "") .. (path or M.SSE_PATH)
end

--- Every `provider/model` pair the config can reach, for model pickers.
function M.availableModels(configValue)
  local out = {}
  for id, provider in pairs(M.list(configValue)) do
    local configured = ((configValue.provider or {})[id] or {}).models
    if configured and util.count(configured) > 0 then
      for modelID, entry in pairs(configured) do
        out[#out + 1] = {
          id = id .. "/" .. modelID,
          name = entry.name or modelID,
          provider = provider.name or id,
          available = config.apiKey(configValue, provider) ~= nil,
        }
      end
    end
  end
  table.sort(out, function(a, b) return a.id < b.id end)
  return out
end

return M

end

-- src/llm.lua
__sources["llm"] = function(...)
do end
-- OpenAI-compatible chat completions client.
--
-- Mirrors opencode's OpenAI Chat protocol: `/chat/completions` on the trimmed
-- base URL, a bearer credential, and a body that omits empty fields. ComputerCraft
-- buffers whole responses, so a `stream: true` request is read in full and the SSE
-- frames are reassembled here.

local json = require("json")
local http = require("http")
local provider = require("provider")

local M = {}

M.FINISH = {
  stop = "stop",
  length = "length",
  content_filter = "content-filter",
  function_call = "tool-calls",
  tool_calls = "tool-calls",
}

local function headerValue(model, key, fallback)
  local headers = model.headers or {}
  local direct = headers[key]
  if direct then
    return direct
  end
  for name, value in pairs(headers) do
    if name:lower() == key:lower() then
      return value
    end
  end
  return fallback
end

--- Drop keys whose value is nil, json.null, or an empty array, as the protocol requires.
local function compact(table_)
  local out = {}
  for key, value in pairs(table_) do
    if value ~= nil and value ~= json.null then
      if type(value) ~= "table" or #value > 0 then
        out[key] = value
      end
    end
  end
  return out
end

--- Build the request body. Empty fields are omitted so we never send `tools: []`.
function M.body(request)
  local model = request.model
  local options = model.options or {}
  -- Per-request generation settings win over the provider defaults.
  local generation = request.generation or {}

  local body = compact({
    model = model.id,
    messages = request.messages or {},
    tools = request.tools and #request.tools > 0 and request.tools or nil,
    tool_choice = request.tool_choice,
    stream = request.stream and true or nil,
    max_tokens = generation.maxTokens or options.maxTokens,
    temperature = generation.temperature or options.temperature,
    top_p = generation.topP or options.topP,
    frequency_penalty = generation.frequencyPenalty,
    presence_penalty = generation.presencePenalty,
    seed = generation.seed,
    stop = generation.stop,
    reasoning_effort = options.reasoningEffort,
    store = options.store,
    prompt_cache_key = options.promptCacheKey,
  })

  if request.stream then
    body.stream_options = { include_usage = true }
  end
  return body
end

local function requestHeaders(model)
  local headers = {
    ["content-type"] = "application/json",
    ["accept"] = "text/event-stream",
  }
  if model.apiKey and model.apiKey ~= "" then
    headers["authorization"] = "Bearer " .. model.apiKey
  end
  for key, value in pairs(model.headers or {}) do
    headers[key:lower()] = value
  end
  headers["content-type"] = headerValue(model, "content-type", headers["content-type"])
  return headers
end

--- Collapse streamed deltas into the same shape the non-streamed path returns.
local function fromStream(response, onDelta)
  onDelta = onDelta or function() end
  local content, reasoning = {}, {}
  local toolCalls = {}
  local finish, usage

  for _, frame in ipairs(http.parseSse(response.body)) do
    local event = json.decode(frame)
    if type(event) == "table" then
      if event.usage and type(event.usage) == "table" then
        usage = event.usage
      end
      local choice = (event.choices or {})[1]
      if type(choice) == "table" then
        if type(choice.finish_reason) == "string" then
          finish = choice.finish_reason
        end
        local delta = choice.delta
        if type(delta) == "table" then
          if type(delta.reasoning_content) == "string" then
            reasoning[#reasoning + 1] = delta.reasoning_content
          end
          if type(delta.content) == "string" then
            content[#content + 1] = delta.content
            onDelta(delta.content)
          end
          for _, call in ipairs(delta.tool_calls or {}) do
            local index = call.index or (#toolCalls)
            local entry = toolCalls[index + 1] or { name = "", arguments = "" }
            if type(call.id) == "string" and call.id ~= "" then
              entry.id = call.id
            end
            if type(call["function"]) == "table" then
              if type(call["function"].name) == "string" and call["function"].name ~= "" then
                entry.name = entry.name .. call["function"].name
              end
              if type(call["function"].arguments) == "string" then
                entry.arguments = entry.arguments .. call["function"].arguments
              end
            end
            toolCalls[index + 1] = entry
          end
        end
      end
    end
  end

  return { content = table.concat(content), reasoning = table.concat(reasoning), toolCalls = toolCalls, finish = finish, usage = usage }
end

--- Normalise a non-streamed choice.
local function fromChoice(choice, usage)
  local message = choice.message
  local toolCalls = {}
  for index, call in ipairs(message.tool_calls or {}) do
    toolCalls[index] = {
      id = call.id,
      name = (call["function"] or {}).name,
      arguments = (call["function"] or {}).arguments or "",
    }
  end
  return {
    content = type(message.content) == "string" and message.content or "",
    reasoning = type(message.reasoning_content) == "string" and message.reasoning_content or "",
    toolCalls = toolCalls,
    finish = choice.finish_reason,
    usage = usage,
  }
end

--- Map the provider's finish_reason, mirroring opencode's translation table.
local function mapFinish(reason, hasToolCalls)
  local mapped = M.FINISH[reason or ""]
  if not mapped then
    return "unknown"
  end
  -- Many OpenAI-compatible servers report "stop" even when they emitted tool calls.
  if mapped == "stop" and hasToolCalls then
    return "tool-calls"
  end
  return mapped
end

--- Translate provider usage into the project's token shape.
local function mapUsage(usage)
  if type(usage) ~= "table" then
    return nil
  end
  local input = usage.prompt_tokens or 0
  local output = usage.completion_tokens or 0
  local cached = (usage.prompt_tokens_details or {}).cached_tokens
  local reasoning = (usage.completion_tokens_details or {}).reasoning_tokens
  return {
    input = input,
    output = output,
    reasoning = reasoning or 0,
    cacheRead = cached or 0,
    cacheWrite = 0,
    total = usage.total_tokens or (input + output),
  }
end

--- Run one chat completion.
--
-- `request.messages` is a list of already-lowered OpenAI wire messages, `request.tools`
-- a list of `{ type = "function", function = { name, description, parameters } }`.
-- `options.onDelta` streams text when the request asked for `stream`.
--
-- Returns a normalized result table, or `nil, message` on failure.
function M.chat(request, options)
  options = options or {}
  local model = request.model
  local stream = request.stream and true or false

  local response, err = http.postJson(provider.url(model, "/chat/completions"), M.body(request), {
    headers = requestHeaders(model),
    timeout = options.timeout or (model.options or {}).timeout or http.DEFAULT_TIMEOUT,
    maxBytes = options.maxBytes or 8 * 1024 * 1024,
    -- A streamed body is an event stream, not a JSON document, so it is left
    -- undecoded here and split into frames by `fromStream`.
    decode = not stream,
  })
  if not response then
    return nil, err
  end

  local result
  if stream then
    result = fromStream(response, options.onDelta)
  else
    local choice = (response.data.choices or {})[1]
    if type(choice) ~= "table" or type(choice.message) ~= "table" then
      return nil, "the response contained no choices"
    end
    result = fromChoice(choice, response.data.usage)
    if options.onDelta and #result.content > 0 then
      options.onDelta(result.content)
    end
  end

  result.finish = mapFinish(result.finish, #result.toolCalls > 0)
  result.usage = mapUsage(result.usage)
  result.raw = response.data
  return result
end

--- Decode the JSON arguments string a model attached to a tool call.
function M.parseArguments(raw)
  if raw == nil or raw == "" then
    return {}
  end
  if type(raw) == "table" then
    return json.dropNulls(raw)
  end
  local decoded, err = json.decode(raw)
  if type(decoded) ~= "table" then
    return nil, err or "arguments were not a JSON object"
  end
  return json.dropNulls(decoded)
end

return M

end

-- src/permission.lua
__sources["permission"] = function(...)
do end
-- Permission rules and the interactive approval prompt.
--
-- Evaluation follows opencode: the last matching rule across the ruleset wins,
-- and the default when nothing matches is "ask". Approvals granted for the
-- session are appended to the session ruleset so later calls are silent.

local util = require("util")

local M = {}

M.ALLOW, M.DENY, M.ASK = "allow", "deny", "ask"

--- Last rule matching both permission and pattern, or an implicit "ask".
function M.evaluate(permission, pattern, ...)
  local rulesets = { ... }
  local found = nil
  for _, ruleset in ipairs(rulesets) do
    for _, rule in ipairs(ruleset or {}) do
      local rulePermission = rule.permission or rule[1] or "*"
      local rulePattern = rule.pattern or rule[2] or "*"
      if util.wildcard(permission, rulePermission) and util.wildcard(pattern, rulePattern) then
        found = { action = rule.action or rule[3] or M.ASK, permission = permission, pattern = pattern }
      end
    end
  end
  return found or { action = M.ASK, permission = permission, pattern = pattern }
end

--- Check a set of patterns at once, returning "allow", "deny" or "ask".
function M.evaluateAll(permission, patterns, ...)
  local needsAsk = false
  for _, pattern in ipairs(patterns) do
    local rule = M.evaluate(permission, pattern, ...)
    if rule.action == M.DENY then
      return M.DENY, pattern
    end
    if rule.action == M.ASK then
      needsAsk = true
    end
  end
  if needsAsk then
    return M.ASK
  end
  return M.ALLOW
end

--- Read a single line from a monitor, returning nil on end of input.
local function prompt(question, monitor)
  if not monitor or not term then
    return "n"
  end
  monitor.write(question)
  monitor.setCursorBlink(true)
  local line = monitor.readLine()
  monitor.setCursorBlink(false)
  if line == nil then
    return "n"
  end
  return util.trim(line):lower()
end

--- Ask the operator to approve `permission` for `patterns`.
--
-- Returns "allow", "deny", or "feedback:<message>" — a rejection carrying the
-- operator's explanation, which the agent loop feeds back to the model so it can
-- correct course instead of retrying blindly.
function M.ask(input)
  if input.ruleset then
    local action = M.evaluateAll(input.permission, input.patterns, input.ruleset)
    if action ~= M.ASK then
      return action
    end
  end

  local patterns = input.patterns or { "*" }
  local shown = {}
  for index, pattern in ipairs(patterns) do
    if index > 4 then
      shown[#shown + 1] = string.format("  ...and %d more", #patterns - 4)
      break
    end
    shown[#shown + 1] = "  " .. pattern
  end

  local lines = { string.format("Permission required: %s", input.permission), table.concat(shown, "\n") }
  if input.title then
    lines[#lines + 1] = input.title
  end
  lines[#lines + 1] = "[y] once  [a] always  [n] no"

  local reply = prompt(table.concat(lines, "\n") .. "\n> ", input.monitor)
  if reply == "y" or reply == "yes" then
    return M.ALLOW
  end
  if reply == "a" or reply == "always" then
    for _, pattern in ipairs(input.always or patterns) do
      input.session.permission[#input.session.permission + 1] = {
        permission = input.permission,
        pattern = pattern,
        action = M.ALLOW,
      }
    end
    return M.ALLOW
  end
  if reply == "n" or reply == "no" or reply == "" then
    return M.DENY
  end
  return "feedback:" .. reply
end

--- Normalise a config permission entry into a ruleset.
function M.ruleset(entries)
  local out = {}
  for _, entry in ipairs(entries or {}) do
    if type(entry) == "string" then
      out[#out + 1] = { permission = entry, pattern = "*", action = M.ALLOW }
    elseif type(entry) == "table" then
      out[#out + 1] = {
        permission = entry.permission or "*",
        pattern = entry.pattern or "*",
        action = entry.action or M.ALLOW,
      }
    end
  end
  return out
end

return M

end

-- src/truncate.lua
__sources["truncate"] = function(...)
do end
-- Tool output truncation.
--
-- Mirrors opencode: output over the line or byte limit is written to
-- `opencode/tool-output/` and the model gets a preview plus a pointer to the full
-- text. Direction matters — shell output is a tail so the most recent lines stay
-- visible, everything else is a head.

local env = require("environment")
local util = require("util")

local M = {}

M.MAX_LINES = 2000
M.MAX_BYTES = 50 * 1024

function M.directory()
  return env.combine(env.cwd(), "opencode", "tool-output")
end

--- Write `text` to the truncation directory and return the file path.
function M.write(text)
  local path = env.combine(M.directory(), util.id("tool") .. ".txt")
  if not env.mkdirs(M.directory()) then
    return nil
  end
  if env.write(path, text) then
    return path
  end
  return nil
end

--- Keep the first `maxLines` lines / `maxBytes` bytes of `text`.
local function head(text, maxLines, maxBytes)
  local kept, bytes = {}, 0
  for index, line in ipairs(util.lines(text)) do
    if index > maxLines then
      return table.concat(kept, "\n"), index - 1, "lines"
    end
    local size = #line + 1
    if bytes + size > maxBytes then
      return table.concat(kept, "\n"), nil, "bytes"
    end
    bytes = bytes + size
    kept[#kept + 1] = line
  end
  return text, nil, nil
end

--- Keep the last `maxLines` lines / `maxBytes` bytes of `text`.
local function tail(text, maxLines, maxBytes)
  local lines = util.lines(text)
  local kept, bytes = {}, 0
  for index = #lines, 1, -1 do
    if #kept >= maxLines then
      return table.concat(kept, "\n"), index, "lines"
    end
    local size = #lines[index] + 1
    if bytes + size > maxBytes then
      return table.concat(kept, "\n"), nil, "bytes"
    end
    bytes = bytes + size
    table.insert(kept, 1, lines[index])
  end
  return text, nil, nil
end

--- Clamp `text` to the limits, saving the full output when it does not fit.
--
-- Returns `text` unchanged, or the preview followed by a note naming the file
-- that holds the complete output.
function M.output(text, options)
  options = options or {}
  local maxLines = options.maxLines or M.MAX_LINES
  local maxBytes = options.maxBytes or M.MAX_BYTES
  local direction = options.direction or "head"

  if #text <= maxBytes and #util.lines(text) <= maxLines + 1 then
    return text
  end

  -- A single `and ... or ...` expression would collapse to one value, so the
  -- branch is chosen first and the result is unpacked separately.
  local preview, removed, unit
  if direction == "tail" then
    preview, removed, unit = tail(text, maxLines, maxBytes)
  else
    preview, removed, unit = head(text, maxLines, maxBytes)
  end
  local path = M.write(text)
  if not path then
    return preview
  end

  local note = string.format(
    "The tool call succeeded but the output was truncated. Full output saved to: %s\nUse Grep to search the full content or Read with offset/limit to view specific sections.",
    path
  )
  if direction == "tail" then
    return string.format("...%s %s truncated...\n\n%s\n\n%s", removed or "many", unit or "lines", note, preview)
  end
  return string.format("%s\n\n...%s %s truncated...\n\n%s", preview, removed or "many", unit or "lines", note)
end

return M

end

-- src/tool/bash.lua
__sources["tool/bash"] = function(...)
do end
-- The `bash` tool: run a command in the ComputerCraft shell.
--
-- CC's shell is not a POSIX shell, so the command runs through `shell.run`. Output
-- is redirected to a temp file so it can be captured and tail-truncated without
-- flooding the terminal. When the `shell` builtin exists the command is spawned
-- with `bg`, which gives us a pid to poll for the timeout and to kill.

local env = require("environment")
local util = require("util")
local truncate = require("truncate")
local registry = require("tool/registry")

local DEFAULT_TIMEOUT_MS = 120000

local DESCRIPTION = [[Executes a command in the ComputerCraft shell with an optional timeout.

Be aware: this is the ComputerCraft shell, not bash. Supported syntax is limited:
- pipes (|), redirection (> >> 2>&1), background (&), and simple sequencing with ;
- builtins: cd, dir/ls, mkdir, rm/del, cp, mv, type/cat, echo, clear, exit, and
  any program installed under /rom/programs or on PATH
- `&&` is not supported; chain dependent commands in a single call separated by `;`
  and check the output

Working directory:
All commands run in the session working directory. Use the `workdir` parameter
instead of a `cd` prefix, so the permission check sees the real target path.

Usage notes:
  - The command argument is required.
  - You can specify an optional timeout in milliseconds. Commands time out after
    120000ms by default.
  - Output longer than the truncation limit is tail-truncated, so the most recent
    lines stay visible and the full text is saved to a file you can grep or read.
  - Do not use this tool for reading, writing, or searching files; use the Read,
    Write, Edit, Glob, and Grep tools for those.
  - You can issue several independent bash calls in one message; they run in order
    but a single call per command keeps the output attributable.

# ComputerCraft specifics
- Programs are Lua programs in /rom/programs or in a directory on PATH. A computer
  is limited in CPU and memory: prefer small, bounded commands over large scans.
- `shell.run` returns immediately for backgrounded commands; the output file may
  still be growing when the tool returns.
- File paths always start with `/` and use `/` as the separator. There is no
  current-directory-relative shorthand, and there is no `which`-free shell.
- The `edit`/`write` tools are the right way to create or modify files. Using
  redirection through bash works but is not tracked by the permission system.]]

local function quote(value)
  return env.quote(value)
end

--- Commands whose first token changes the working directory, exempt from
--- permission checks because the workdir parameter covers that case.
local CD_COMMANDS = { cd = true, chdir = true, pushd = true, popd = true }

--- Split a command line on `;` so each segment can be permission checked.
local function segments(command)
  local out = {}
  for piece in command:gmatch("[^;]+") do
    local trimmed = util.trim(piece)
    if trimmed ~= "" then
      out[#out + 1] = trimmed
    end
  end
  return out
end

--- Derive the permission pattern for a command: `git status` -> `git status`,
--- and the always-pattern `git *` that covers its subcommands.
local function arityPatterns(segment)
  local tokens = {}
  for token in segment:gmatch("%S+") do
    tokens[#tokens + 1] = token:gsub("^%s+", "")
  end
  local name = tokens[1] and tokens[1]:gsub("[;&|].*$", "")
  if not name or name == "" then
    return segment, nil
  end
  local always = name
  if #tokens > 1 and not tokens[2]:match("^%-") then
    always = name .. " " .. tokens[2]
  end
  return segment, always .. " *"
end

--- Poll a spawned job until it finishes, the timeout expires, or we are aborted.
-- Returns whether the job timed out and whether it was aborted; the exit code is
-- read from `shell.getJobInfoEx`, which retains info after the job is reaped.
local function waitForJob(pid, timeoutMs, ctx)
  local deadline = os.time() + math.ceil(timeoutMs / 1000)
  while shell.getJobInfo(pid) do
    if os.time() >= deadline then
      shell.kill(pid)
      return true, false
    end
    if ctx and ctx.aborted and ctx.aborted() then
      shell.kill(pid)
      return false, true
    end
    util.sleep(0.1)
  end
  local info = shell.getJobInfoEx and shell.getJobInfoEx(pid)
  return false, false, type(info) == "table" and info.exitCode or nil
end

--- Run `command`, returning its exit code, captured output, and any failure note.
local function run(command, workdir, timeoutMs, ctx)
  local outputPath = env.combine(truncate.directory(), util.id("bash") .. ".out")
  if not env.mkdirs(truncate.directory()) then
    error("could not create the output directory " .. truncate.directory(), 0)
  end

  local line = command
  if workdir and workdir ~= "" then
    line = "cd " .. quote(workdir) .. " ; " .. line
  end
  line = line .. " > " .. quote(outputPath) .. " 2>&1"

  local notes = {}
  local exitCode

  if shell.which and shell.which("shell") and shell.getJobInfo and shell.getJobInfoEx then
    local pid = shell.run("bg shell " .. quote(line))
    if type(pid) ~= "number" or pid <= 0 then
      env.remove(outputPath)
      error("could not start the command", 0)
    end
    local timedOut, aborted
    timedOut, aborted, exitCode = waitForJob(pid, timeoutMs, ctx)
    if timedOut then
      notes[#notes + 1] = string.format(
        "the command was terminated after exceeding the timeout of %d ms. Retry with a larger timeout if it was not waiting for input.",
        timeoutMs
      )
    end
    if aborted then
      notes[#notes + 1] = "the user aborted the command"
    end
  else
    -- No cancellable job handle available. The command still runs with its output
    -- captured, but on timeout it cannot be killed and is reported as abandoned.
    local abandoned = false
    local coroutine = coroutine.create(function()
      exitCode = shell.run(line)
    end)
    local timer = os.startTimer(math.ceil(timeoutMs / 1000))
    local event = parallel.waitForAny({ coroutine, timer })
    if event == timer then
      abandoned = true
      notes[#notes + 1] = string.format(
        "the command was still running after the timeout of %d ms and was abandoned; its output file may still be growing.",
        timeoutMs
      )
    end
    if abandoned and shell.kill then
      shell.kill(tostring(coroutine))
    end
  end

  local captured = env.read(outputPath) or ""
  env.remove(outputPath)
  return exitCode, captured, notes
end

registry.define({
  id = "bash",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      command = { type = "string", description = "The command to execute" },
      timeout = {
        type = "number",
        description = "Optional timeout in milliseconds. Defaults to 120000.",
      },
      workdir = {
        type = "string",
        description = "The directory to run the command in. Defaults to the session working directory. Use this instead of a cd prefix.",
      },
    },
    required = { "command" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local command = args.command
    if type(command) ~= "string" or util.trim(command) == "" then
      error("The command argument is required.", 0)
    end
    local timeout = tonumber(args.timeout) or DEFAULT_TIMEOUT_MS
    if timeout < 0 then
      error("Invalid timeout value: " .. tostring(args.timeout) .. ". Timeout must be a positive number.", 0)
    end
    local workdir = args.workdir and env.resolve(args.workdir, ctx.cwd) or ctx.cwd

    local patterns, always = {}, {}
    for _, segment in ipairs(segments(command)) do
      local name = segment:match("^(%S+)")
      if not (name and CD_COMMANDS[name]) then
        local pattern, alwaysPattern = arityPatterns(segment)
        patterns[#patterns + 1] = pattern
        if alwaysPattern then
          always[#always + 1] = alwaysPattern
        end
      end
    end
    if not env.contains(ctx.root, workdir) then
      registry.guard(ctx, "external_directory", { workdir .. "/*" }, { workdir .. "/*" },
        "working outside " .. ctx.root)
    end
    registry.guard(ctx, "bash", patterns, always, command)

    local exitCode, captured, notes = run(command, workdir, timeout, ctx)

    local limits = registry.limits(ctx.config)
    local output = truncate.output(captured, {
      maxLines = limits.maxLines,
      maxBytes = limits.maxBytes,
      direction = "tail",
    })
    if output == "" then
      output = "(no output)"
    end
    if #notes > 0 then
      output = output .. "\n\n<shell_metadata>\n" .. table.concat(notes, "\n") .. "\n</shell_metadata>"
    end

    return {
      title = command,
      metadata = { output = output, exit = exitCode },
      output = output,
    }
  end,
})

return true

end

-- src/tool/read.lua
__sources["tool/read"] = function(...)
do end
-- The `read` tool: file contents or a directory listing.

local env = require("environment")
local util = require("util")
local registry = require("tool/registry")

local DEFAULT_LIMIT = 2000
local MAX_LINE_LENGTH = 2000
local MAX_BYTES = 50 * 1024
local SAMPLE_BYTES = 4096

local DESCRIPTION = [[Read a file or directory from the filesystem. If the path does not exist, an error is returned.

Usage:
- The filePath parameter should be an absolute path. Relative paths resolve against
  the session working directory.
- By default, this tool returns up to 2000 lines from the start of the file.
- The offset parameter is the line number to start from (1-indexed).
- To read later sections, call this tool again with a larger offset.
- Use the grep tool to find specific content in large files or files with long lines.
- If you are unsure of the correct file path, use the glob tool to look up filenames.
- Contents are returned with each line prefixed by its line number as `<line>: <content>`.
  For example, a file containing "foo" returns "1: foo". For directories, entries are
  returned one per line, with a trailing `/` for subdirectories.
- Any line longer than 2000 characters is truncated.
- Read a larger window rather than many small slices; each call costs context.]]

local BINARY_EXTENSIONS = {
  zip = true, tar = true, gz = true, bz2 = true, xz = true, ["7z"] = true,
  exe = true, dll = true, so = true, class = true, jar = true, war = true,
  doc = true, docx = true, xls = true, xlsx = true, ppt = true, pptx = true,
  odt = true, ods = true, odp = true, bin = true, dat = true, obj = true,
  o = true, a = true, lib = true, wasm = true, pyc = true, pyo = true,
  png = true, jpg = true, jpeg = true, gif = true, webp = true, pdf = true,
  nbt = true, wav = true, ogg = true,
}

--- Extension-based first, then a content sample: a NUL byte or a high ratio of
--- non-printable bytes means we should not hand this to the model as text.
local function isBinary(path, sample)
  local extension = path:match("%.([%w]+)$")
  if extension and BINARY_EXTENSIONS[extension:lower()] then
    return true
  end
  if not sample or #sample == 0 then
    return false
  end
  if sample:find("\0", 1, true) then
    return true
  end
  local printable = 0
  for index = 1, #sample do
    local byte = sample:byte(index)
    if byte == 9 or byte == 10 or byte == 13 or (byte >= 32 and byte < 127) or byte >= 128 then
      printable = printable + 1
    end
  end
  return printable / #sample < 0.7
end

--- Suggest up to three sibling names that resemble the missing file's basename.
local function didYouMean(path)
  local directory = env.dirname(path)
  local base = env.basename(path)
  local suggestions = {}
  for _, name in ipairs(env.listDir(directory)) do
    if util.fuzzyContains(name, base) or util.fuzzyContains(base, name) then
      suggestions[#suggestions + 1] = env.combine(directory, name)
      if #suggestions == 3 then
        break
      end
    end
  end
  return suggestions
end

local function listDirectory(path, args)
  local names = env.listDir(path)
  local offset = math.max(1, tonumber(args.offset) or 1)
  local limit = tonumber(args.limit) or DEFAULT_LIMIT
  local start = offset - 1

  local entries = {}
  for index, name in ipairs(names) do
    if index > start and #entries < limit then
      local full = env.combine(path, name)
      entries[#entries + 1] = (env.isDir(full) and name .. "/" or name)
    end
  end

  local shown = #entries
  local more = start + shown < #names
  local footer = more
      and string.format(
        "\n(Showing %d of %d entries. Use 'offset' parameter to read beyond entry %d)",
        shown, #names, offset + shown
      )
    or string.format("\n(%d entries)", #names)

  return {
    title = path,
    metadata = { count = #names },
    output = table.concat({ "<path>" .. path .. "</path>", "<type>directory</type>", "<entries>",
      table.concat(entries, "\n"), footer, "</entries>" }, "\n"),
  }
end

registry.define({
  id = "read",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      filePath = { type = "string", description = "The path to the file or directory to read" },
      offset = { type = "number", description = "The line number to start reading from (1-indexed)" },
      limit = { type = "number", description = "The maximum number of lines to read (defaults to 2000)" },
    },
    required = { "filePath" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local path = env.resolve(args.filePath, ctx.cwd)
    if not util.startswith(path, ctx.root) then
      registry.guard(ctx, "external_directory", { path }, { path }, "reading outside " .. ctx.root)
    end
    registry.guard(ctx, "read", { path }, { path })

    if env.isDir(path) then
      return listDirectory(path, args)
    end
    if not env.exists(path) then
      local suggestions = didYouMean(path)
      if #suggestions > 0 then
        error(string.format("File not found: %s\n\nDid you mean one of these?\n%s", path, table.concat(suggestions, "\n")), 0)
      end
      error("File not found: " .. path, 0)
    end

    local content, cut = env.readLimited(path, MAX_BYTES)
    if isBinary(path, content:sub(1, SAMPLE_BYTES)) then
      error("Cannot read binary file: " .. path, 0)
    end

    local lines = util.lines(content)
    local count = #lines
    local offset = math.max(1, tonumber(args.offset) or 1)
    local limit = tonumber(args.limit) or DEFAULT_LIMIT

    if count < offset and not (count == 0 and offset == 1) then
      error(string.format("Offset %d is out of range for this file (%d lines)", offset, count), 0)
    end

    local body = {}
    local bytes = 0
    local index = offset
    while index <= count and #body < limit do
      local line = lines[index]
      if bytes + #line > MAX_BYTES then
        cut = true
        break
      end
      if #line > MAX_LINE_LENGTH then
        line = line:sub(1, MAX_LINE_LENGTH) .. string.format("... (line truncated to %d chars)", MAX_LINE_LENGTH)
      end
      bytes = bytes + #line
      body[#body + 1] = string.format("%d: %s", index, line)
      index = index + 1
    end

    local last = index - 1
    local footer
    if cut then
      footer = string.format(
        "\n\n(Output capped at %s. Showing lines %d-%d. Use offset=%d to continue.)",
        util.byteLabel(MAX_BYTES), offset, last, last + 1
      )
    elseif last < count then
      footer = string.format(
        "\n\n(Showing lines %d-%d of %d. Use offset=%d to continue.)",
        offset, last, count, last + 1
      )
    else
      footer = string.format("\n\n(End of file - total %d lines)", count)
    end

    return {
      title = path,
      metadata = { lines = count },
      output = string.format("<path>%s</path>\n<type>file</type>\n<content>\n%s%s\n</content>",
        path, table.concat(body, "\n"), footer),
    }
  end,
})

return true

end

-- src/tool/write.lua
__sources["tool/write"] = function(...)
do end
-- The `write` tool: create or overwrite a file.

local env = require("environment")
local util = require("util")
local registry = require("tool/registry")

local DESCRIPTION = [[Writes a file to the filesystem.

Usage:
- This tool overwrites the existing file at the provided path.
- Prefer editing an existing file over rewriting it; use the Edit tool for changes
  to part of a file.
- Parent directories are created automatically.
- Do not proactively create documentation files (*.md) or README files. Only create
  documentation when explicitly requested.
- Only use emojis if the user explicitly requests it.
- Text files are written as UTF-8 with \n line endings. A byte order mark already
  present in the file is preserved.]]

registry.define({
  id = "write",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      filePath = { type = "string", description = "The path of the file to write" },
      content = { type = "string", description = "The content to write to the file" },
    },
    required = { "filePath", "content" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local path = env.resolve(args.filePath, ctx.cwd)
    local content = args.content
    if type(content) ~= "string" then
      error("The content argument is required and must be a string.", 0)
    end
    if env.isDir(path) then
      error("Path is a directory, not a file: " .. path, 0)
    end
    if not util.startswith(path, ctx.root) then
      registry.guard(ctx, "external_directory", { path }, { path }, "writing outside " .. ctx.root)
    end
    registry.guard(ctx, "edit", { path }, { path }, "write " .. path)

    local existed = env.exists(path)
    local bom = ""
    if existed then
      local existing = env.readLimited(path, 3) or ""
      if existing:sub(1, 3) == "\239\187\191" then
        bom = "\239\187\191"
      end
    end

    if not env.mkdirs(env.dirname(path)) then
      error("Could not create the directory " .. env.dirname(path), 0)
    end
    if not env.write(path, bom .. content) then
      error("Could not write " .. path, 0)
    end

    local action = existed and "Updated" or "Created"
    return {
      title = action .. " " .. path,
      metadata = { path = path, created = not existed },
      output = string.format("%s file successfully: %s (%d bytes)", action, path, #bom + #content),
    }
  end,
})

return true

end

-- src/tool/edit.lua
__sources["tool/edit"] = function(...)
do end
-- The `edit` tool: exact string replacement.
--
-- Ports the replacer chain from opencode's edit tool. A model rarely produces a
-- byte-exact match because of indentation or line-ending drift, so the chain
-- widens the search progressively rather than failing on the first mismatch. Each
-- replacer yields candidate spans; a candidate is only accepted when it is unique
-- (unless replaceAll is set), which is what turns an ambiguous edit into an error
-- instead of a wrong write.

local env = require("environment")
local util = require("util")
local registry = require("tool/registry")

local DESCRIPTION = [[Performs exact string replacements in files.

Usage:
- You must have read the file at least once in this conversation before editing, so
  that the content you pass in matches what is really there.
- When copying text out of Read output, keep the exact indentation that appears after
  the `N: ` line-number prefix. Never include the prefix itself in oldString or
  newString.
- Prefer editing an existing file over rewriting it. Do not create new files unless
  explicitly required.
- The edit FAILS if oldString is not found, with "Could not find oldString in the file".
- The edit FAILS if oldString appears more than once, telling you to add surrounding
  context or to set replaceAll.
- Use replaceAll for renaming a symbol across a file.]]

--- Byte offsets of every occurrence of `search` in `content`.
local function occurrences(content, search)
  local positions = {}
  if search == "" then
    return positions
  end
  local from = 1
  while true do
    local start = content:find(search, from, true)
    if not start then
      return positions
    end
    positions[#positions + 1] = start
    from = start + 1
  end
end

--- Refuse a fuzzy match that would swallow much more of the file than was asked for.
local function isDisproportionate(search, oldString)
  local oldLines = #util.lines(oldString)
  local searchLines = #util.lines(search)
  if searchLines >= math.max(oldLines + 3, oldLines * 2) then
    return true
  end
  if oldLines == 1 then
    return false
  end
  return #util.trim(search) > math.max(#util.trim(oldString) + 500, #util.trim(oldString) * 4)
end

--- Spans where `needle`'s lines match `haystack`'s lines, comparing trimmed text.
-- Returns a list of `{ start, finish }` byte ranges into `haystack`.
local function matchByTrimmedLine(haystack, needle)
  local haystackLines = util.lines(haystack)
  local needleLines = util.lines(needle)
  local spans = {}
  if #needleLines == 0 or #haystackLines < #needleLines then
    return spans
  end

  local offsets, running = {}, 1
  for _, line in ipairs(haystackLines) do
    offsets[#offsets + 1] = running
    running = running + #line + 1
  end

  for index = 1, #haystackLines - #needleLines + 1 do
    local matched = true
    for offset = 1, #needleLines do
      if util.trim(haystackLines[index + offset - 1]) ~= util.trim(needleLines[offset]) then
        matched = false
        break
      end
    end
    if matched then
      local start = offsets[index]
      local last = index + #needleLines - 1
      local finish = offsets[last] + #haystackLines[last] - 1
      spans[#spans + 1] = { start = start, finish = finish }
    end
  end
  return spans
end

--- Collapse whitespace runs, returning the collapsed text and a map back to the original.
local function collapseWhitespace(text)
  local out, map = {}, {}
  local index, count = 1, 0
  while index <= #text do
    local char = text:sub(index, index)
    if char:match("%s") then
      while index <= #text and text:sub(index, index):match("%s") do
        index = index + 1
      end
      out[#out + 1] = " "
      count = count + 1
      map[count] = index - 1
    else
      out[#out + 1] = char
      count = count + 1
      map[count] = index
      index = index + 1
    end
  end
  return table.concat(out), map
end

local function stripIndent(text)
  local lines = util.lines(text)
  local shortest = nil
  for _, line in ipairs(lines) do
    local stripped = line:match("^%s*")
    if #line > #stripped and (not shortest or #stripped < #shortest) then
      shortest = #stripped
    end
  end
  if not shortest or shortest == 0 then
    return text
  end
  local out = {}
  for _, line in ipairs(lines) do
    out[#out + 1] = line:sub(math.min(shortest + 1, #line + 1))
  end
  return table.concat(out, "\n")
end

--- Candidate spans to try, in widening order of leniency.
local function candidates(content, oldString)
  local out = {}

  for _, position in ipairs(occurrences(content, oldString)) do
    out[#out + 1] = content:sub(position, position + #oldString - 1)
  end

  for _, span in ipairs(matchByTrimmedLine(content, oldString)) do
    out[#out + 1] = content:sub(span.start, span.finish)
  end

  local collapsedOld = stripIndent(oldString)
  if collapsedOld ~= oldString then
    for _, span in ipairs(matchByTrimmedLine(content, collapsedOld)) do
      out[#out + 1] = content:sub(span.start, span.finish)
    end
  end

  local collapsedContent, map = collapseWhitespace(content)
  local collapsedNeedle = collapseWhitespace(oldString)
  local at = collapsedContent:find(collapsedNeedle, 1, true)
  if at and at > 1 then
    local start = map[at] or 1
    local finish = map[at + #collapsedNeedle - 1] or #content
    if finish >= start then
      out[#out + 1] = content:sub(start, math.min(finish, #content))
    end
  end

  return out
end

--- Replace every occurrence of `search`, treating both sides as plain text.
local function gsubLiteral(content, search, replacement)
  local escaped = search:gsub("([^%w])", "%%%1")
  local out = content:gsub(escaped, function()
    return replacement
  end)
  return out
end

--- Apply the replacement, raising a model-readable message on ambiguity.
local function replace(content, oldString, newString, replaceAll)
  if oldString == newString then
    error("No changes to apply: oldString and newString are identical.", 0)
  end
  if util.trim(oldString) == "" then
    error(
      "oldString cannot be empty when editing an existing file. Provide the exact text to replace, or use write for an intentional full-file replacement.",
      0
    )
  end

  local found, ambiguous = false, false
  for _, search in ipairs(candidates(content, oldString)) do
    local positions = occurrences(content, search)
    if #positions > 0 then
      found = true
      if isDisproportionate(search, oldString) then
        error(
          "Refusing replacement because the matched span is much larger than oldString. Re-read the file and provide the full exact oldString for the intended replacement.",
          0
        )
      end
      if replaceAll then
        return gsubLiteral(content, search, newString)
      end
      if #positions == 1 then
        local start = positions[1]
        return content:sub(1, start - 1) .. newString .. content:sub(start + #search)
      end
      ambiguous = true
    end
  end

  if ambiguous then
    error("Found multiple matches for oldString. Provide more surrounding lines in oldString to identify the correct match.", 0)
  end
  error("Could not find oldString in the file. It must match exactly, including whitespace, indentation, and line endings.", 0)
end

registry.define({
  id = "edit",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      filePath = { type = "string", description = "The path of the file to modify" },
      oldString = { type = "string", description = "The text to replace" },
      newString = { type = "string", description = "The text to replace it with. Must differ from oldString." },
      replaceAll = { type = "boolean", description = "Replace every occurrence of oldString. Defaults to false." },
    },
    required = { "filePath", "oldString", "newString" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local path = env.resolve(args.filePath, ctx.cwd)
    local oldString, newString = args.oldString, args.newString
    if type(oldString) ~= "string" or type(newString) ~= "string" then
      error("The oldString and newString arguments are required and must be strings.", 0)
    end
    if oldString == newString then
      error("No changes to apply: oldString and newString are identical.", 0)
    end
    if env.isDir(path) then
      error("Path is a directory, not a file: " .. path, 0)
    end
    if not util.startswith(path, ctx.root) then
      registry.guard(ctx, "external_directory", { path }, { path }, "editing outside " .. ctx.root)
    end

    if not env.exists(path) then
      if util.trim(oldString) ~= "" then
        error("File " .. path .. " not found", 0)
      end
      registry.guard(ctx, "edit", { path }, { path }, "create " .. path)
      if not env.mkdirs(env.dirname(path)) then
        error("Could not create the directory " .. env.dirname(path), 0)
      end
      env.write(path, newString)
      return { title = "Created " .. path, metadata = { path = path, created = true },
        output = "Created file successfully: " .. path }
    end

    registry.guard(ctx, "edit", { path }, { path }, "edit " .. path)

    local content = env.read(path) or ""
    local bom = ""
    if content:sub(1, 3) == "\239\187\191" then
      bom = "\239\187\191"
      content = content:sub(4)
    end

    local ending = content:find("\r\n", 1, true) and "\r\n" or "\n"
    local normalize = function(text)
      return (text:gsub("\r\n", "\n"):gsub("\n", ending))
    end

    local updated = replace(content, normalize(oldString), normalize(newString), args.replaceAll and true or false)
    if not env.write(path, bom .. updated) then
      error("Could not write " .. path, 0)
    end

    return {
      title = "Edited " .. path,
      metadata = { path = path, created = false },
      output = "Edit applied successfully.",
    }
  end,
})

return true

end

-- src/pattern.lua
__sources["pattern"] = function(...)
do end
-- Pattern matching: glob patterns and a regex-to-Lua translator.
--
-- ComputerCraft has no regex engine, so grep needs a translation layer. The
-- supported subset covers what models actually send in practice: literals,
-- character classes, the standard escapes, quantifiers, groups, alternation, and
-- anchors. Lua patterns have no upper-bounded repeat, so `{n,m}` is expanded into
-- `n` mandatory copies plus `m-n` optional ones.

local M = {}

--- Convert a glob pattern to a Lua pattern. `**` spans directory boundaries.
function M.globToPattern(glob)
  local out = { "^" }
  local index = 1
  while index <= #glob do
    local char = glob:sub(index, index)
    if char == "*" then
      if glob:sub(index, index + 1) == "**" then
        index = index + 1
        if glob:sub(index + 1, index + 1) == "/" then
          -- "**/" spans any number of directories, including none. A lazy
          -- any-character run covers both, and the separator is consumed with
          -- it; Lua has no quantifier for a group, so ".-/" is not expressible.
          out[#out + 1] = ".-"
          index = index + 1
        else
          out[#out + 1] = ".*"
        end
      else
        out[#out + 1] = "[^/]*"
      end
    elseif char == "?" then
      out[#out + 1] = "[^/]"
    elseif char == "[" then
      local close = glob:find("]", index + 2, true)
      if close then
        local body = glob:sub(index + 1, close - 1)
        if body:sub(1, 1) == "!" then
          body = "^" .. body:sub(2)
        end
        out[#out + 1] = "[" .. body .. "]"
        index = close
      else
        out[#out + 1] = "%["
      end
    else
      out[#out + 1] = char:gsub("([%^%$%(%)%%%.%[%]%+%-%*%?])", "%%%1")
    end
    index = index + 1
  end
  out[#out + 1] = "$"
  return table.concat(out)
end

--- True when a path matches a glob pattern, used by the include filters.
function M.matchesGlob(path, glob)
  return M.find({ M.globToPattern(glob) }, path) ~= nil
end

--- Regex character classes. Lua's `%w` is letters and digits only, so `\w` needs
--- the underscore spelled out to match what a model means by a word character.
local CLASSES = {
  d = "%d",
  D = "%D",
  w = "[%w_]",
  W = "[^%w_]",
  s = "%s",
  S = "%S",
  l = "%l",
  u = "%u",
  p = "%p",
  P = "%P",
}

local function escapeLiteral(char)
  return char:gsub("([%^%$%(%)%%%.%[%]%+%-%*%?])", "%%%1")
end

--- Read a `[...]` class starting at `i`, returning its text and the next index.
local function readClass(body, i)
  local close = body:find("]", i + 1, true)
  if not close then
    return nil, i + 1
  end
  local inner = body:sub(i + 1, close - 1)
  if inner:sub(1, 1) == "!" then
    inner = "^" .. inner:sub(2)
  end
  return "[" .. inner .. "]", close + 1
end

--- Read a `{...}` quantifier, returning the min/max counts and the next index.
local function readRepeat(body, i)
  local close = body:find("}", i, true)
  if not close then
    return nil, nil, i + 1
  end
  local inner = body:sub(i + 1, close - 1)
  local min, max = inner:match("^(%d*),(%d*)$")
  if not min then
    return nil, nil, i + 1
  end
  min = min == "" and 0 or tonumber(min)
  max = max == "" and math.huge or tonumber(max)
  if max < min then
    return nil, nil, i + 1
  end
  return min, max, close + 1
end

--- Expand an atom and a quantifier into plain Lua pattern fragments.
local function expand(atom, min, max)
  if min == 0 and max == math.huge then
    return atom .. "*"
  end
  if min == 1 and max == math.huge then
    return atom .. "+"
  end
  if min == 0 and max == 1 then
    return atom .. "?"
  end
  local out = {}
  for _ = 1, min do
    out[#out + 1] = atom
  end
  for _ = min + 1, math.min(max, min + 8) do
    out[#out + 1] = atom .. "?"
  end
  return table.concat(out)
end

--- True when `text` is a single translatable atom, i.e. something a Lua
--- quantifier can be attached to.
local function isSingleAtom(text)
  return #text == 1 or (text:sub(1, 1) == "[" and text:sub(-1) == "]")
end

--- Split a translated fragment into everything but its last atom and that atom
-- with any quantifier stripped, so a new quantifier can be attached to it.
local function splitLastAtom(text)
  local body = text
  while body ~= "" do
    local last = body:sub(-1)
    if last == "*" or last == "+" or last == "?" then
      body = body:sub(1, -2)
    else
      break
    end
  end
  if body:sub(-1) == "]" then
    local head = body:match("^(.*)%[")
    if head then
      return head, body:sub(#head + 1)
    end
  end
  if body:sub(-2, -2) == "%" then
    return body:sub(1, -3), body:sub(-2)
  end
  return body:sub(1, -2), body:sub(-1)
end

--- Apply a quantifier to a translated fragment, re-attaching it to the last atom
-- when the fragment is more than one atom long.
local function quantify(text, min, max)
  if min == 1 and max == 1 then
    return text
  end
  if isSingleAtom(text) then
    return expand(text, min, max)
  end
  local head, atom = splitLastAtom(text)
  return head .. expand(atom, min, max)
end

--- Index of the ')' that closes the group opened at `i`, or nil.
local function findCloseParen(body, i)
  local depth, inClass = 0, false
  local index = i
  while index <= #body do
    local char = body:sub(index, index)
    if char == "\\" then
      index = index + 2
    elseif inClass then
      if char == "]" then
        inClass = false
      end
      index = index + 1
    elseif char == "[" then
      inClass = true
      index = index + 1
    elseif char == "(" then
      depth = depth + 1
      index = index + 1
    elseif char == ")" then
      depth = depth - 1
      if depth == 0 then
        return index
      end
      index = index + 1
    else
      index = index + 1
    end
  end
  return nil
end

--- Read a `(...)` group starting at `i`, returning its body and the next index.
--
-- Handles the group prefixes models emit: capturing, `?:`, `?<name>`, inline
-- flags, and lookaround, which is dropped along with its body because Lua has
-- no lookaround.
local function readGroup(body, i)
  local index = i + 1
  if body:sub(index, index) == "?" then
    local second = body:sub(index + 1, index + 1)
    if second == ":" then
      index = index + 2
    elseif second == "<" then
      local third = body:sub(index + 2, index + 2)
      if third == "=" or third == "!" then
        local close = findCloseParen(body, index + 2)
        return close and "" or nil, close and close + 1 or #body + 1
      end
      local close = body:find(">", index + 2, true)
      index = close and close + 1 or index + 2
    else
      -- Inline flags: "(?i)" drops the flag, "(?i:...)" keeps the body.
      local close = body:find(")", index + 1, true)
      local colon = body:find(":", index + 1, true)
      if close and (not colon or close < colon) then
        return "", close + 1
      end
      if colon then
        index = colon + 1
      else
        return "", #body + 1
      end
    end
  end

  local close = findCloseParen(body, i)
  if not close then
    return nil, #body + 1
  end
  return body:sub(index, close - 1), close + 1
end

--- Translate one alternative (no top-level `|`) into a Lua pattern.
--
-- Groups are transparent: their body is inlined. A quantifier after a group
-- attaches to the group's own text when that text is a single atom, which covers
-- the common `(\w+)` case, and to its last atom otherwise. Lua patterns cannot
-- repeat a group, so `(ab)+` is an approximation of `X+` for multi-character
-- groups.
local function translateBody(body)
  local out = {}
  local index = 1

  while index <= #body do
    local char = body:sub(index, index)
    local atom, nextIndex

    -- Anchors only mean anything at the very ends. Anywhere else they are
    -- literals, and a quantifier must never be attached to one. An anchor
    -- emits its character and leaves `atom` unset, so no quantifier is applied.
    if char == "^" and index == 1 then
      out[#out + 1] = "^"
      nextIndex = 2
    elseif char == "$" and index == #body then
      out[#out + 1] = "$"
      nextIndex = #body + 1
    elseif char == "\\" then
      local escape = body:sub(index + 1, index + 1)
      atom = CLASSES[escape] or ("%" .. escape)
      nextIndex = index + 2
    elseif char == "[" then
      local text, after = readClass(body, index)
      if not text then
        atom, nextIndex = "%[", index + 1
      else
        atom, nextIndex = text, after
      end
    elseif char == "(" then
      local inner, after = readGroup(body, index)
      if inner == nil then
        atom, nextIndex = "%(", index + 1
      else
        local min, max = 1, 1
        local quantifier = body:sub(after, after)
        if quantifier == "*" or quantifier == "+" or quantifier == "?" then
          min = quantifier == "+" and 1 or 0
          max = quantifier == "?" and 1 or math.huge
          after = after + 1
        elseif quantifier == "{" then
          local repeatMin, repeatMax, afterRepeat = readRepeat(body, after)
          if repeatMin then
            min, max = repeatMin, repeatMax
            after = afterRepeat
          end
        end
        out[#out + 1] = quantify(translateBody(inner), min, max)

        -- A trailing '?' makes the group's quantifier lazy, which Lua has no syntax for.
        if body:sub(after, after) == "?" then
          after = after + 1
        end
        nextIndex = after
      end
    elseif char == "." then
      atom, nextIndex = ".", index + 1
    elseif char == "{" then
      local min, max, after = readRepeat(body, index)
      if min then
        for _ = 1, math.min(min, 8) do
          out[#out + 1] = "."
        end
        nextIndex = after
        if max > min then
          out[#out + 1] = ".*"
        end
      else
        atom, nextIndex = "%{", index + 1
      end
    elseif char == ")" then
      atom, nextIndex = "%)", index + 1
    else
      atom, nextIndex = escapeLiteral(char), index + 1
    end

    if atom then
      -- No quantifier means exactly one occurrence, not one-or-more.
      local min, max = 1, 1
      local quantifier = body:sub(nextIndex, nextIndex)
      if quantifier == "*" or quantifier == "+" or quantifier == "?" then
        min = quantifier == "+" and 1 or 0
        max = quantifier == "?" and 1 or math.huge
        nextIndex = nextIndex + 1
      elseif quantifier == "{" then
        local repeatMin, repeatMax, after = readRepeat(body, nextIndex)
        if repeatMin then
          min, max = repeatMin, repeatMax
          nextIndex = after
        end
      end
      out[#out + 1] = expand(atom, min, max)

      -- A trailing '?' makes the quantifier lazy, which Lua has no syntax for.
      if body:sub(nextIndex, nextIndex) == "?" then
        nextIndex = nextIndex + 1
      end
    end

    index = nextIndex
  end

  return table.concat(out)
end

--- Split a regex on top-level `|`, ignoring separators inside groups or classes.
local function splitAlternatives(regex)
  local parts, current = {}, {}
  local depth, inClass = 0, false
  local index = 1
  while index <= #regex do
    local char = regex:sub(index, index)
    if char == "\\" then
      current[#current + 1] = char .. regex:sub(index + 1, index + 1)
      index = index + 2
    elseif char == "[" then
      inClass = true
      current[#current + 1] = char
      index = index + 1
    elseif char == "]" then
      inClass = false
      current[#current + 1] = char
      index = index + 1
    elseif char == "(" and not inClass then
      depth = depth + 1
      current[#current + 1] = char
      index = index + 1
    elseif char == ")" and not inClass then
      depth = depth - 1
      current[#current + 1] = char
      index = index + 1
    elseif char == "|" and not inClass and depth == 0 then
      parts[#parts + 1] = table.concat(current)
      current = {}
      index = index + 1
    else
      current[#current + 1] = char
      index = index + 1
    end
  end
  parts[#parts + 1] = table.concat(current)
  return parts
end

--- Compile a regex into a list of Lua patterns, one per top-level alternative,
--- anchored so a match means the whole alternative matched.
-- Invalid patterns are skipped rather than raised, so a bad regex still greps.
function M.compile(regex)
  local out = {}
  for _, alternative in ipairs(splitAlternatives(regex or "")) do
    local translated = translateBody(alternative)
    if translated:sub(1, 1) ~= "^" then
      translated = "^" .. translated
    end
    if translated:sub(-1) ~= "$" then
      translated = translated .. "$"
    end
    if pcall(string.find, "", translated) then
      out[#out + 1] = translated
    end
  end
  return out
end

--- Compile without adding anchors, for substring searches within a line. Anchors
--- the regex wrote itself are still honoured.
function M.compilePartial(regex)
  local out = {}
  for _, alternative in ipairs(splitAlternatives(regex or "")) do
    local translated = translateBody(alternative)
    if pcall(string.find, "", translated) then
      out[#out + 1] = translated
    end
  end
  return out
end

--- Locate a match, returning start and end byte offsets, or nil.
function M.find(patterns, subject)
  for _, pattern in ipairs(patterns) do
    local ok, start, finish = pcall(string.find, subject, pattern)
    if ok and start then
      return start, finish
    end
  end
  return nil
end

--- True when any pattern matches anywhere in `subject`.
function M.test(patterns, subject)
  return M.find(patterns, subject) ~= nil
end

return M

end

-- src/tool/glob.lua
__sources["tool/glob"] = function(...)
do end
-- The `glob` tool: find files by name pattern.

local env = require("environment")
local util = require("util")
local pattern = require("pattern")
local registry = require("tool/registry")

local LIMIT = 100

local DESCRIPTION = [[Fast file pattern matching that works with any codebase size.
- Supports glob patterns such as "**/*.lua" or "/src/**/*.ts"
- Returns matching file paths
- Use this when you need to find files by name
- Issue several speculative glob calls in one message when you are unsure of the
  layout; each is cheap compared to the context a full listing would cost.]]

registry.define({
  id = "glob",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      pattern = { type = "string", description = "The glob pattern to match against file paths" },
      path = { type = "string", description = "The directory to search. Defaults to the session working directory." },
      limit = { type = "number", description = "Maximum number of results. Defaults to 100." },
    },
    required = { "pattern" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local glob = args.pattern
    if type(glob) ~= "string" or glob == "" then
      error("The pattern argument is required.", 0)
    end
    local root = args.path and env.resolve(args.path, ctx.cwd) or ctx.cwd
    local limit = math.min(tonumber(args.limit) or LIMIT, LIMIT)

    local compiled = pattern.globToPattern(util.startswith(glob, "/") and glob:sub(2) or glob)
    local matches = {}
    local total = 0

    env.walk(root, {
      onFile = function(path)
        local relative = path:sub(#root + 1)
        relative = util.startswith(relative, "/") and relative:sub(2) or relative
        if pattern.find({ compiled }, relative) then
          total = total + 1
          if #matches < limit then
            matches[#matches + 1] = path
          end
        end
      end,
    })

    table.sort(matches)
    if #matches == 0 then
      return { title = glob, metadata = { count = 0 }, output = "No files found" }
    end

    local output = table.concat(matches, "\n")
    if total > limit then
      output = output
        .. string.format(
          "\n\n(Results are truncated: showing the first %d of %d results. Use a more specific path or pattern.)",
          limit, total
        )
    end

    return { title = glob, metadata = { count = total }, output = output }
  end,
})

return true

end

-- src/tool/grep.lua
__sources["tool/grep"] = function(...)
do end
-- The `grep` tool: search file contents.
--
-- CC has no regex engine, so patterns go through the translator in
-- `src/pattern.lua`, which supports the subset models normally send.

local env = require("environment")
local util = require("util")
local pattern = require("pattern")
local registry = require("tool/registry")

local LIMIT = 100
local SKIP_DIRECTORIES = {
  [".git"] = true, [".svn"] = true, ["node_modules"] = true, [".cache"] = true,
  ["opencode"] = true, [".Trash"] = true, ["__pycache__"] = true,
}

local DESCRIPTION = [[Fast content search that works with any codebase size.
- Searches file contents using a regular expression
- Filter which files are searched with the include parameter, e.g. "*.lua" or "*.md"
- Returns file paths with line numbers and the matching lines
- Use this when you need to find code containing a specific pattern
- Run several independent searches in one message rather than guessing a single
  broad pattern; each search is cheap compared to the context a full read would cost.]]

--- True when `path` should be searched, per the include filter.
local function included(path, includes)
  if not includes then
    return true
  end
  for _, include in ipairs(includes) do
    if pattern.matchesGlob(path, include) or pattern.matchesGlob(env.basename(path), include) then
      return true
    end
  end
  return false
end

--- Split a comma separated include filter into glob patterns.
local function parseIncludes(raw)
  if type(raw) ~= "string" or raw == "" then
    return nil
  end
  local out = {}
  for piece in raw:gmatch("[^,]+") do
    local trimmed = util.trim(piece)
    if trimmed ~= "" then
      out[#out + 1] = trimmed
    end
  end
  return #out > 0 and out or nil
end

registry.define({
  id = "grep",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      pattern = { type = "string", description = "The regular expression to search for" },
      path = { type = "string", description = "The directory to search. Defaults to the session working directory." },
      include = { type = "string", description = "Comma separated glob patterns limiting which files are searched, e.g. \"*.lua\"" },
      limit = { type = "number", description = "Maximum number of matching lines to return. Defaults to 100." },
    },
    required = { "pattern" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local regex = args.pattern
    if type(regex) ~= "string" or regex == "" then
      error("The pattern argument is required.", 0)
    end
    local root = args.path and env.resolve(args.path, ctx.cwd) or ctx.cwd
    local limit = math.min(tonumber(args.limit) or LIMIT, LIMIT)
    local includes = parseIncludes(args.include)
    local compiled = pattern.compilePartial(regex)

    if #compiled == 0 then
      error("The pattern could not be compiled: " .. regex, 0)
    end

    local hits, total = {}, 0
    local truncated = false

    env.walk(root, {
      onDir = function(path)
        local name = env.basename(path)
        if name == ".git" or SKIP_DIRECTORIES[name] then
          return false
        end
        return true
      end,
      onFile = function(path)
        if truncated or not included(path, includes) then
          return
        end
        local content = env.readLimited(path, 512 * 1024)
        if not content then
          return
        end
        local matched = {}
        for number, line in ipairs(util.lines(content)) do
          if pattern.find(compiled, line) then
            total = total + 1
            if #hits < limit then
              matched[#matched + 1] = string.format("  Line %d: %s", number, util.trim(line))
            else
              truncated = true
            end
          end
        end
        if #matched > 0 then
          hits[#hits + 1] = { path = path, lines = matched }
        end
      end,
    })

    if #hits == 0 then
      return { title = regex, metadata = { count = 0 }, output = "No matches found" }
    end

    local blocks = {}
    for _, hit in ipairs(hits) do
      blocks[#blocks + 1] = hit.path .. ":\n" .. table.concat(hit.lines, "\n")
    end

    local header = truncated
        and string.format("Found %d matches (showing the first %d, more are available)", total, limit)
      or string.format("Found %d matches", total)
    local output = header .. "\n\n" .. table.concat(blocks, "\n\n")
    if truncated then
      output = output .. "\n\n(Results are truncated. Use a more specific pattern or path.)"
    end

    return { title = regex, metadata = { count = total }, output = output }
  end,
})

return true

end

-- src/tool/webfetch.lua
__sources["tool/webfetch"] = function(...)
do end
-- The `webfetch` tool: retrieve a URL and return its content as text.

local util = require("util")
local http = require("http")
local registry = require("tool/registry")

local MAX_BYTES = 5 * 1024 * 1024
local MAX_TIMEOUT = 120

local DESCRIPTION = [[Fetches content from a URL and returns it as text.

Usage notes:
  - The URL must be fully formed, including the scheme. http:// is upgraded to https://
  - The format may be "text" (default) or "html". HTML is returned as source.
  - Only the body is returned; navigation links and framing are stripped.
  - This tool is read-only and does not modify any files.
  - Large pages are truncated. Fetch a more specific URL when the result is cut off.]]

--- Very small HTML-to-text conversion: drop script/style/nav noise and tags.
local function htmlToText(html)
  local text = html
  for _, tag in ipairs({ "script", "style", "noscript", "svg", "head" }) do
    text = text:gsub("<" .. tag .. "[^>]*>.-</" .. tag .. ">", " ")
  end
  text = text:gsub("<!--.-%-%->", " ")
  text = text:gsub("<br%s*/?>", "\n")
  text = text:gsub("</p>", "\n\n")
  text = text:gsub("</h[1-6]>", "\n\n")
  text = text:gsub("</li>", "\n")
  text = text:gsub("<li[^>]*>", "- ")
  text = text:gsub("<a[^>]*href=\"([^\"]*)\"[^>]*>(.-)</a>", function(_, href, label)
    return util.trim(label) ~= "" and string.format("[%s](%s)", util.trim(label), href) or " "
  end)
  text = text:gsub("<[^>]+>", " ")
  text = text:gsub("&nbsp;", " "):gsub("&amp;", "&"):gsub("&lt;", "<")
  text = text:gsub("&gt;", ">"):gsub("&quot;", '"'):gsub("&#39;", "'")
  text = text:gsub("[ \t]+", " ")
  text = text:gsub(" *\n *", "\n")
  text = text:gsub("\n{3,}", "\n\n")
  return util.trim(text)
end

registry.define({
  id = "webfetch",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      url = { type = "string", description = "The URL to fetch" },
      format = { type = "string", description = "Either \"text\" (default) or \"html\"" },
      timeout = { type = "number", description = "Timeout in seconds, up to 120. Defaults to 30." },
    },
    required = { "url" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local url = args.url
    if type(url) ~= "string" or url == "" then
      error("The url argument is required.", 0)
    end
    if url:match("^http://") then
      url = "https://" .. url:sub(8)
    end
    if not url:match("^https://") then
      error("The url must start with http:// or https://, got: " .. args.url, 0)
    end

    local timeout = math.min(tonumber(args.timeout) or 30, MAX_TIMEOUT)
    local response, err = http.request(url, { timeout = timeout, maxBytes = MAX_BYTES })
    if not response then
      error("Could not fetch " .. url .. ": " .. tostring(err), 0)
    end
    if response.status < 200 or response.status >= 300 then
      error("Could not fetch " .. url .. ": " .. http.errorMessage(response), 0)
    end

    local body = args.format == "html" and response.body or htmlToText(response.body or "")
    if body == "" then
      body = "(empty response)"
    end

    return {
      title = url,
      metadata = { url = url, status = response.status, bytes = #(response.body or "") },
      output = string.format("<url>%s</url>\n<status>%d</status>\n<content>\n%s\n</content>", url, response.status, body),
    }
  end,
})

return true

end

-- src/tool/todowrite.lua
__sources["tool/todowrite"] = function(...)
do end
-- The `todowrite` tool: maintain a structured task list for the session.

local json = require("json")
local registry = require("tool/registry")

local DESCRIPTION = [[Create and maintain a structured task list for the current session. Tracks progress, organizes multi-step work, and surfaces status to the user.

## When to use
Use proactively when:
- The task requires 3 or more distinct steps or actions (not 3 tool calls for one conceptual step)
- The work is non-trivial and benefits from planning
- The user provides multiple tasks (numbered or comma-separated) or asks for a todo list
- New instructions arrive: capture them as todos
- You start a task: mark it in_progress (only one at a time) before working
- You finish a task: mark it completed and add any follow-ups you discovered

## When NOT to use
Skip when:
- The work is a single straightforward task (or fewer than 3 trivial steps)
- The request is purely informational or conversational
- Tracking adds no organizational value

## States
- pending: not started
- in_progress: actively working (exactly ONE at a time)
- completed: finished successfully

## Rules
- Update status in real time; do not batch completions
- Mark completed only after the work is actually done and verified, never based on intent
- Keep exactly one in_progress while work remains
- If blocked or partial, keep it in_progress and add a follow-up todo describing the blocker

## Examples

Use it:
- "Add a dark mode toggle and run the tests" -> multi-step work with explicit verification
- "Rename X to Y across the repo" -> search reveals 5 occurrences in 3 files
- "Implement authentication, catalog, cart, and checkout" -> several complex features

Skip it:
- "How do I print Hello World?" -> informational
- "Add a single comment to a function" -> one edit
- "Run npm install and report what happened" -> one command

When in doubt, use it.]]

local VALID_STATUS = { pending = true, in_progress = true, completed = true, cancelled = true }
local VALID_PRIORITY = { high = true, medium = true, low = true }

registry.define({
  id = "todowrite",
  description = DESCRIPTION,
  parameters = {
    type = "object",
    properties = {
      todos = {
        type = "array",
        description = "The complete updated todo list. Send every todo, not just the ones that changed.",
        items = {
          type = "object",
          properties = {
            content = { type = "string", description = "The task description" },
            status = { type = "string", description = "One of: pending, in_progress, completed, cancelled" },
            priority = { type = "string", description = "One of: high, medium, low" },
          },
          required = { "content", "status", "priority" },
          additionalProperties = false,
        },
      },
    },
    required = { "todos" },
    additionalProperties = false,
  },
  execute = function(args, ctx)
    local todos = args.todos
    if type(todos) ~= "table" then
      error("The todos argument is required and must be an array.", 0)
    end

    local normalised = {}
    local active = 0
    for index, todo in ipairs(todos) do
      if type(todo) ~= "table" or type(todo.content) ~= "string" or todo.content == "" then
        error("Each todo needs a non-empty content string; todo " .. index .. " is invalid.", 0)
      end
      local status = VALID_STATUS[todo.status] and todo.status or "pending"
      if status == "in_progress" then
        active = active + 1
      end
      normalised[#normalised + 1] = {
        content = todo.content,
        status = status,
        priority = VALID_PRIORITY[todo.priority] and todo.priority or "medium",
      }
    end

    if active > 1 then
      error("Exactly one todo may be in_progress at a time, but " .. active .. " were.", 0)
    end

    registry.guard(ctx, "todowrite", { "*" }, { "*" })
    ctx.session.todos = normalised

    return {
      title = string.format("%d todos", #normalised),
      metadata = { todos = normalised },
      output = json.encode(normalised, "  "),
    }
  end,
})

return true

end

-- src/tool/registry.lua
__sources["tool/registry"] = function(...)
do end
-- Tool registry.
--
-- A tool is `{ id, description, parameters, execute }` where `parameters` is a
-- JSON Schema object describing the tool's arguments. `execute(args, ctx)`
-- returns `{ title, metadata, output }`, or raises with a string to signal a tool
-- error that is reported back to the model.

local json = require("json")
local util = require("util")
local permission = require("permission")
local truncate = require("truncate")

local M = {}

M.builtin = {}

local BUILTIN_MODULES = {
  "tool/bash",
  "tool/read",
  "tool/write",
  "tool/edit",
  "tool/glob",
  "tool/grep",
  "tool/webfetch",
  "tool/todowrite",
}

--- Load the built-in tool modules so their `define` calls have run.
--
-- Idempotent, and deliberately not done at the bottom of this file. Each tool
-- module requires the registry back, so a tool required while the registry is
-- still loading is a require cycle: `require` marks the module it is loading with
-- a sentinel in `package.loaded` and refuses to resolve the inner call. Calling
-- this from the agent loop or `/tools` happens once the registry is complete, and
-- `M.loaded` makes even a second call a no-op.
function M.load()
  if M.loaded then
    return M.builtin
  end
  M.loaded = true
  for _, name in ipairs(BUILTIN_MODULES) do
    require(name)
  end
  return M.builtin
end

--- Declare a tool. Keeping this in one place makes the schema and the executor
--- impossible to drift apart.
function M.define(spec)
  M.builtin[#M.builtin + 1] = {
    id = spec.id,
    description = spec.description,
    parameters = spec.parameters,
    execute = spec.execute,
  }
end

--- Convert a tool into the OpenAI wire shape.
function M.toWire(tool)
  return {
    type = "function",
    ["function"] = {
      name = tool.id,
      description = tool.description,
      parameters = tool.parameters,
    },
  }
end

function M.list(enabled)
  M.load()
  if not enabled then
    return M.builtin
  end
  local out = {}
  for _, tool in ipairs(M.builtin) do
    if enabled[tool.id] ~= false then
      out[#out + 1] = tool
    end
  end
  return out
end

function M.get(id)
  M.load()
  for _, tool in ipairs(M.builtin) do
    if tool.id == id then
      return tool
    end
  end
  return nil
end

function M.ids(enabled)
  local out = {}
  for _, tool in ipairs(M.list(enabled)) do
    out[#out + 1] = tool.id
  end
  return out
end

--- Request approval for a tool action, honouring the session ruleset.
-- Returns true when allowed, or raises a permission error the model will see.
function M.guard(ctx, permissionID, patterns, always, title)
  local decision = permission.ask({
    permission = permissionID,
    patterns = patterns or { "*" },
    always = always or patterns or { "*" },
    ruleset = ctx.permission,
    session = ctx.session,
    monitor = ctx.monitor,
    title = title,
  })
  if decision == permission.ALLOW then
    return true
  end
  if util.startswith(decision, "feedback:") then
    error("Permission denied by the user: " .. decision:sub(10), 0)
  end
  error("Permission denied by the user for " .. permissionID .. ": " .. table.concat(patterns or {}, ", "), 0)
end

local truncateLimits

function M.limits(config)
  if not truncateLimits or truncateLimits.config ~= config then
    local options = (config and config.tool_output) or {}
    truncateLimits = {
      config = config,
      maxLines = options.max_lines or truncate.MAX_LINES,
      maxBytes = options.max_bytes or truncate.MAX_BYTES,
    }
  end
  return truncateLimits
end

--- Apply output limits unless the tool already reported its own truncation.
function M.finish(tool, ctx, result)
  if result.metadata and result.metadata.truncated ~= nil then
    return result
  end
  local limits = M.limits(ctx.config)
  local truncated = truncate.output(result.output, {
    maxLines = limits.maxLines,
    maxBytes = limits.maxBytes,
    direction = "head",
  })
  if truncated == result.output then
    return result
  end
  result.metadata = result.metadata or {}
  result.metadata.truncated = true
  result.output = truncated
  return result
end

--- Run one tool by id, converting failures into a structured result.
function M.execute(id, rawArguments, ctx)
  local tool = M.get(id)
  if not tool then
    return {
      status = "error",
      error = "Unknown tool '" .. id .. "'. Available tools: " .. table.concat(M.ids(ctx.enabled), ", "),
    }
  end
  local arguments = type(rawArguments) == "table" and json.dropNulls(rawArguments) or {}

  local ok, result = pcall(tool.execute, arguments, ctx)
  if not ok then
    local message = tostring(result):gsub("^.-:%d+: ", "")
    if message:find("Permission denied") then
      return { status = "denied", error = message }
    end
    return { status = "error", error = message }
  end

  result = M.finish(tool, ctx, result)
  return { status = "completed", title = result.title, output = result.output, metadata = result.metadata }
end

return M

end

-- src/prompt.lua
__sources["prompt"] = function(...)
do end
-- System prompts.
--
-- Adapted from opencode's prompt templates. The structure is preserved (tone,
-- proactiveness, conventions, task workflow, tool policy) but rewritten for the
-- ComputerCraft environment, where the shell is CC's rather than bash and the
-- files are Lua programs with a limited filesystem.

local env = require("environment")
local config = require("config")
local registry = require("tool/registry")
local truncate = require("truncate")

local M = {}

M.BASE = [[You are opencode, an interactive agent running on a ComputerCraft computer in Minecraft. You help the user with software engineering tasks using the tools available to you.

You are running inside a Lua sandbox, not a normal operating system. The rules below follow from that and matter for every task.

# Environment
- The shell is the ComputerCraft shell, not bash. It has pipes, `>` redirection, `&` for background, and `;` for sequencing. It does NOT have `&&`, `$VAR` expansion, `~`, or glob expansion. Programs are Lua files under /rom/programs or on PATH.
- Files live under the root `/` and always use absolute paths with `/` separators. There is no home directory concept beyond the root.
- Your own source is at the path shown in the environment block. Lua 5.1: no `goto` in older builds, no integer division operator, `unpack` not `table.unpack`, and no `os.execute` or `io` writes. Use `fs` and `shell` from ComputerCraft.
- Lua memory and CPU are tiny. Do not plan to process megabytes in a single Lua operation, and do not read huge files in one call; use the Read tool with offset/limit.
- There is no internet browsing other than the WebFetch tool, and no package manager. Dependencies do not exist unless they are already on the computer.

# Tone and style
Be concise and direct. Output is displayed on a terminal, so short answers are best.
- Answer questions directly. One or two sentences when that answers the question.
- Do not add preamble, postamble, or a summary of what you were about to do.
- Do not restate the user's request back to them.
- Explain what you are doing only when a command changes state or the reasoning is not obvious.
- Only use emojis if the user explicitly requests it.
- Never invent a URL unless you are confident it exists. You may use URLs the user gave you or that appear in local files.

# Code style
- IMPORTANT: do not add any comments unless asked.
- Follow the conventions of the file you are editing: match its naming, formatting, comment density, and structure. Read neighbouring code before adding to it.
- Never assume a library is available. Check that the code already uses it before relying on it.
- Never print or commit secrets, including API keys in opencode.json.
- Match the surrounding code's style even where you would have written it differently.

# Doing tasks
- Understand the code before changing it. Use Glob and Grep to locate things, and Read to read them. Batch independent searches together.
- Prefer the dedicated tools over the shell: Read and Write and Edit for files, Glob for finding, Grep for searching, WebFetch for the web, and Bash only for running programs.
- Verify your work when the project has a way to verify it. On ComputerCraft that usually means running a program or checking output.
- Do not commit, upload, or delete things the user did not ask you to delete.

# Tool usage policy
- You can call several tools in one message. Do so whenever the calls are independent.
- When you are unsure of the file layout, issue speculative searches rather than one broad scan.
- Read a file before editing it. The Edit tool needs the exact text including indentation.
- Do not use Bash with `type`, `cat`, `echo >` or `ls` for file work; use Read, Write, and Glob instead.
- If you do not need a tool, do not call it. Answer from what you already know.]]

M.PLAN = [[# Planning
You are in plan mode. Investigate and produce a plan; do not modify any files or run commands that change state.
- Read and search freely to understand the current implementation.
- Present a concrete, ordered plan and ask the user to approve it before implementing.
- When the user approves, stop planning and switch back to the agent that can edit.]]

M.EXPLORE = [[You are a read-only search agent. Find things and report what you found; do not modify anything.

- Run several independent searches in parallel where possible.
- Report file paths and line numbers so the caller can read the exact locations.
- Quote only the lines that matter, not whole files.
- If a search returns nothing, say so plainly rather than guessing.]]

M.TITLE = [[Generate a short title for a conversation. Reply with the title only, no quotes, no punctuation at the end, and at most 6 words.]]

M.COMPACTION = [[Summarize the conversation so far so it can continue in a fresh context. Preserve, in this order of priority:
1. The user's original request and any explicit constraints.
2. Decisions made and their reasons.
3. Files and functions that were created, changed, or inspected, with paths.
4. What was completed and what remains.
Write it as a dense briefing, not a narrative. Do not include pleasantries.]]

M.MAX_STEPS = [[CRITICAL - MAXIMUM STEPS REACHED

The maximum number of steps for this task has been reached. Tools are disabled until the next user input. Respond with text only.

STRICT REQUIREMENTS:
1. Do NOT make any tool calls.
2. You MUST provide a text response summarising the work done so far.
3. This constraint overrides all other instructions.

Your response must include:
- A statement that the maximum steps have been reached
- A summary of what has been accomplished
- A list of anything that remains
- A recommendation for what to do next]]

local AGENT_PROMPTS = {
  build = M.BASE,
  plan = M.BASE .. "\n" .. M.PLAN,
  general = M.BASE,
  explore = M.EXPLORE,
  title = M.TITLE,
  compaction = M.COMPACTION,
}

--- The environment block injected ahead of every request.
function M.environment(configValue, model)
  local root = env.cwd()
  return string.format(
    "You are powered by the model named %s. The exact model ID is %s/%s.\nHere is some useful information about the environment you are running in:\n<env>\n  Computer: %s\n  Working directory: %s\n  Platform: %s (ComputerCraft, Lua %s)\n  Today's date: %s\n</env>",
    model.name or model.id,
    model.providerID,
    model.id,
    env.computerLabel(),
    root,
    env.isCC and "ComputerCraft" or "host",
    _VERSION or "5.1",
    env.today()
  )
end

--- The current tool list, so the prompt never names a tool that is disabled.
function M.tools(enabled)
  local names = registry.ids(enabled)
  return "Available tools: " .. table.concat(names, ", ") .. "."
end

--- Output limits, so the bash and read prompts quote the real numbers.
function M.limits()
  local options = config.DEFAULTS.tool_output
  return string.format(
    "Tool output is truncated past %d lines or %d bytes; the full text is written to a file you can grep or read with offset/limit.",
    options.max_lines,
    options.max_bytes
  )
end

--- The full system prompt for one request.
function M.system(configValue, agent, model, enabled)
  local base = (configValue.agent or {})[agent] and (configValue.agent[agent].prompt)
    or AGENT_PROMPTS[agent]
    or AGENT_PROMPTS.build
  return table.concat({
    base,
    M.environment(configValue, model),
    M.limits(),
    M.tools(enabled),
  }, "\n\n")
end

return M

end

-- src/session.lua
__sources["session"] = function(...)
do end
-- Session message storage.
--
-- A session is a list of messages; each message has a list of parts. The part
-- union mirrors opencode's schema closely enough to keep the model wire format
-- correct: text, reasoning, tool (with a pending/running/completed/error state),
-- step-start, and step-finish.

local json = require("json")
local util = require("util")
local env = require("environment")

local M = {}

local function newSession(id, title)
  return {
    id = id,
    title = title,
    created = os.time(),
    messages = {},
    todos = {},
    permission = {},
  }
end

--- The title a session has until one is generated for it.
M.DEFAULT_TITLE = "New session"

function M.new(title)
  return newSession(util.id("ses"), title or M.DEFAULT_TITLE)
end

function M.latestUserMessage(session)
  for index = #session.messages, 1, -1 do
    if session.messages[index].role == "user" then
      return session.messages[index]
    end
  end
  return nil
end

function M.latestAssistantMessage(session)
  for index = #session.messages, 1, -1 do
    if session.messages[index].role == "assistant" then
      return session.messages[index]
    end
  end
  return nil
end

--- True when the most recent assistant reply belongs to the newest user message
--- and left nothing outstanding.
--
-- The parent check is what makes a second `agent.run` on the same session do
-- something: after a finished turn there *is* an assistant message, so without it
-- a follow-up question would look like a completed turn and the loop would exit
-- before making a request.
function M.isTurnComplete(session)
  local user = M.latestUserMessage(session)
  if not user then
    return true
  end
  local assistant = M.latestAssistantMessage(session)
  if not assistant or assistant.parentID ~= user.id or not assistant.finish then
    return false
  end
  if assistant.finish == "tool-calls" or assistant.finish == "unknown" then
    return false
  end
  for _, part in ipairs(assistant.parts) do
    if part.type == "tool" and not part.state.providerExecuted and part.state.status ~= "error" then
      return false
    end
  end
  return true
end

function M.addUser(session, text)
  local message = { id = util.id("msg"), role = "user", time = { created = os.time() }, parts = { { type = "text", text = text } } }
  session.messages[#session.messages + 1] = message
  return message
end

--- The first thing the user asked, which is what a session title is built from.
function M.firstUserMessage(session)
  for _, message in ipairs(session.messages) do
    if message.role == "user" and not message.summary then
      return message
    end
  end
  return nil
end

--- The concatenated text of a message, or the empty string.
function M.text(message)
  if not message then
    return ""
  end
  local parts = {}
  for _, part in ipairs(message.parts or {}) do
    if part.type == "text" then
      parts[#parts + 1] = part.text
    end
  end
  return table.concat(parts)
end

function M.addAssistant(session, model)
  local user = M.latestUserMessage(session)
  local message = {
    id = util.id("msg"),
    role = "assistant",
    -- Which user turn this replies to, so a finished turn is not mistaken for an
    -- answer to the next question.
    parentID = user and user.id or nil,
    time = { created = os.time() },
    model = model,
    parts = {},
    cost = 0,
    tokens = { input = 0, output = 0, reasoning = 0, cacheRead = 0, cacheWrite = 0, total = 0 },
  }
  message.parts[#message.parts + 1] = { type = "step-start", time = { start = os.time() } }
  session.messages[#session.messages + 1] = message
  return message
end

function M.addText(message, text)
  local part = { type = "text", text = text, time = { start = os.time() } }
  message.parts[#message.parts + 1] = part
  return part
end

function M.addReasoning(message, text)
  local part = { type = "reasoning", text = text, time = { start = os.time() } }
  message.parts[#message.parts + 1] = part
  return part
end

function M.addToolPart(message, call)
  local part = {
    type = "tool",
    callID = call.id or util.id("call"),
    tool = call.name,
    state = { status = "pending", input = {}, raw = call.arguments or "" },
  }
  message.parts[#message.parts + 1] = part
  return part
end

function M.startTool(part, input)
  part.state.status = "running"
  part.state.input = input
  part.state.time = { start = os.time() }
end

function M.completeTool(part, result)
  part.state.status = "completed"
  part.state.output = result.output
  part.state.title = result.title
  part.state.metadata = result.metadata or {}
  part.state.time = part.state.time or { start = os.time() }
  part.state.time["end"] = os.time()
end

function M.failTool(part, message)
  part.state.status = "error"
  part.state.error = message
  part.state.metadata = part.state.metadata or {}
  part.state.time = part.state.time or { start = os.time() }
  part.state.time["end"] = os.time()
end

function M.finishStep(message, finish, usage)
  message.finish = finish
  if usage then
    message.tokens = usage
  end
  message.parts[#message.parts + 1] = { type = "step-finish", reason = finish, tokens = message.tokens }
  message.time.completed = os.time()
  return message
end

--- Concatenated assistant text across every step of a message.
function M.messageText(message)
  local parts = {}
  for _, part in ipairs(message.parts or {}) do
    if part.type == "text" then
      parts[#parts + 1] = part.text
    end
  end
  return table.concat(parts)
end

--- True when the message is mostly tool bookkeeping and carries no user-facing text.
function M.isSilent(message)
  return #M.messageText(message) == 0
end

local function serialisable(session)
  return {
    id = session.id,
    title = session.title,
    created = session.created,
    todos = session.todos,
    permission = session.permission,
    messages = session.messages,
  }
end

function M.directory()
  return env.combine(env.cwd(), "opencode", "session")
end

function M.save(session)
  local path = env.combine(M.directory(), session.id .. ".json")
  if not env.mkdirs(env.dirname(path)) then
    return nil, "could not create " .. env.dirname(path)
  end
  local encoded = json.encode(serialisable(session), "  ")
  if not encoded then
    return nil, "could not encode the session"
  end
  if not env.write(path, encoded) then
    return nil, "could not write " .. path
  end
  return path
end

function M.load(id)
  local path = env.combine(M.directory(), id .. ".json")
  local content = env.read(path)
  if not content then
    return nil
  end
  local decoded = json.decode(content)
  if type(decoded) ~= "table" then
    return nil
  end
  decoded.permission = decoded.permission or {}
  return decoded
end

--- Every saved session id, newest first.
function M.list()
  local ids = {}
  for _, name in ipairs(env.listDir(M.directory())) do
    local id = name:match("^(ses_[%w]+)%.json$")
    if id then
      ids[#ids + 1] = id
    end
  end
  table.sort(ids, function(a, b) return a > b end)
  return ids
end

return M

end

-- src/agent.lua
__sources["agent"] = function(...)
do end
-- The agent loop.
--
-- One iteration is one provider turn: lower the session into OpenAI wire
-- messages, call the model, run whatever tools it asked for, append the results,
-- and repeat until the model stops calling tools. The loop mirrors opencode's
-- `runLoop`, including the max-steps guard and the doom-loop check that stops a
-- model from repeating the same failing call forever.

local json = require("json")
local util = require("util")
local llm = require("llm")
local prompt = require("prompt")
local session = require("session")
local registry = require("tool/registry")
local permission = require("permission")
local config = require("config")
local provider = require("provider")

local M = {}

local DOOM_LOOP_THRESHOLD = 3
local DEFAULT_STEPS = 25

M.COMPACT_MAX_TOKENS = 1024

--- Resolve the step budget for an agent from config, then the built-in defaults.
local function maxStepsFor(configValue, agent)
  local configured = (configValue.agent or {})[agent]
  if configured and configured.steps then
    return configured.steps
  end
  local fallback = (config.DEFAULTS.agent or {})[agent]
  return fallback and fallback.steps or DEFAULT_STEPS
end

--- Concatenate the text parts of a message.
local function textOf(message)
  local parts = {}
  for _, part in ipairs(message.parts or {}) do
    if part.type == "text" then
      parts[#parts + 1] = part.text
    end
  end
  return table.concat(parts)
end

--- Lower one assistant message and its tool results into wire messages.
local function lowerAssistant(message, out)
  local text = textOf(message)
  local reasoning = ""
  local toolParts = {}
  for _, part in ipairs(message.parts or {}) do
    if part.type == "reasoning" then
      reasoning = reasoning .. part.text
    elseif part.type == "tool" then
      toolParts[#toolParts + 1] = part
    end
  end

  if text == "" and reasoning == "" and #toolParts == 0 then
    return
  end

  local wire = { role = "assistant", content = text ~= "" and text or json.null }
  if reasoning ~= "" then
    wire.reasoning_content = reasoning
  end
  if #toolParts > 0 then
    wire.tool_calls = {}
    for index, part in ipairs(toolParts) do
      wire.tool_calls[index] = {
        id = part.callID,
        type = "function",
        ["function"] = { name = part.tool, arguments = json.encode(part.state.input or {}) },
      }
    end
  end
  out[#out + 1] = wire

  for _, part in ipairs(toolParts) do
    local content
    if part.state.status == "completed" then
      content = part.state.output
    elseif part.state.status == "error" then
      content = "Error: " .. (part.state.error or "the tool failed")
    else
      content = "Error: the tool was interrupted before it finished"
    end
    out[#out + 1] = { role = "tool", tool_call_id = part.callID, content = content }
  end
end

--- Build the full OpenAI wire message list for a request.
function M.lower(current, system, trailer)
  local messages = {}
  if system and system ~= "" then
    messages[1] = { role = "system", content = system }
  end
  for _, message in ipairs(current.messages) do
    if message.role == "user" then
      messages[#messages + 1] = { role = "user", content = textOf(message) }
    else
      lowerAssistant(message, messages)
    end
  end
  if trailer then
    messages[#messages + 1] = { role = "assistant", content = trailer }
  end
  return messages
end

--- True when the newest assistant turn left work for the model to pick up.
function M.hasPendingWork(current)
  return not session.isTurnComplete(current)
end

--- Raise unless the operator wants the repeated call to continue.
local function doomLoopCheck(ctx, part, history)
  history[#history + 1] = part.tool .. ":" .. json.encode(part.state.input or {})
  if #history < DOOM_LOOP_THRESHOLD then
    return
  end
  for index = #history - DOOM_LOOP_THRESHOLD + 2, #history - 1 do
    if history[index] ~= history[#history] then
      return
    end
  end

  local decision = permission.ask({
    permission = "doom_loop",
    patterns = { part.tool },
    always = { part.tool },
    ruleset = ctx.permission,
    session = ctx.session,
    monitor = ctx.monitor,
    title = string.format(
      "The same %s call has run %d times in a row with identical arguments. Continue?",
      part.tool,
      DOOM_LOOP_THRESHOLD
    ),
  })
  if decision == permission.ALLOW then
    return
  end
  error(
    "The same " .. part.tool .. " call was repeated with identical arguments, so it was stopped. "
      .. "Change the arguments or take a different approach.",
    0
  )
end

--- Run every tool the model asked for in this turn, appending results.
local function runTools(ctx, message, calls, history)
  for _, call in ipairs(calls) do
    if ctx.aborted() then
      return
    end

    local part = session.addToolPart(message, call)

    local arguments, parseError = llm.parseArguments(call.arguments)
    if parseError then
      session.failTool(part, "The " .. call.name .. " tool was called with invalid arguments: " .. parseError
        .. ". Rewrite the input so it matches the tool's schema.")
      ctx.on({ type = "tool_start", part = part })
      ctx.on({ type = "tool_end", part = part })
    else
      -- The start event goes out once the arguments are on the part, so a
      -- listener can say what the model is about to do rather than just naming
      -- the tool.
      session.startTool(part, arguments)
      ctx.on({ type = "tool_start", part = part })
      local outcome = registry.execute(call.name, arguments, ctx)
      if outcome.status == "completed" then
        session.completeTool(part, outcome)
      else
        session.failTool(part, outcome.error)
        if outcome.status == "denied" then
          ctx.blocked = true
        end
      end

      if part.state.status == "completed" then
        local ok, err = pcall(doomLoopCheck, ctx, part, history)
        if not ok then
          session.failTool(part, tostring(err))
        end
      end

      ctx.on({ type = "tool_end", part = part })
    end
  end
end

--- Run the agent loop until the model stops calling tools.
--
-- `ctx` supplies: session, config, model, agent, root, cwd, permission, enabled
-- (tool toggles), monitor, on (event sink), and aborted (a predicate).
function M.run(ctx, options)
  options = options or {}
  local current = ctx.session
  local maxSteps = maxStepsFor(ctx.config, ctx.agent)
  local step = 0
  local history = {}

  while true do
    if ctx.aborted() then
      ctx.on({ type = "aborted" })
      return nil, "aborted"
    end
    if not M.hasPendingWork(current) then
      break
    end

    step = step + 1
    if step > maxSteps then
      return session.latestAssistantMessage(current),
        string.format("reached the maximum of %d steps for agent '%s'", maxSteps, ctx.agent)
    end

    local isLastStep = step == maxSteps
    ctx.on({ type = "step", step = step, max = maxSteps })

    -- Once per step, before the request is built, so the request that would have
    -- been too large never goes out.
    local summary = M.compact(ctx)
    if summary then
      ctx.on({ type = "compacted", text = summary })
    end

    local message = session.addAssistant(current, ctx.model)
    local system = prompt.system(ctx.config, ctx.agent, ctx.model, ctx.enabled)
    local messages = M.lower(current, system, isLastStep and prompt.MAX_STEPS or nil)

    local tools = {}
    for _, tool in ipairs(registry.list(ctx.enabled)) do
      tools[#tools + 1] = registry.toWire(tool)
    end

    local textPart
    local onDelta = nil
    if ctx.stream then
      onDelta = function(delta)
        if not textPart then
          textPart = session.addText(message, "")
        end
        textPart.text = textPart.text .. delta
        ctx.on({ type = "text", delta = delta })
      end
    end

    local result, err = llm.chat({
      model = ctx.model,
      messages = messages,
      tools = #tools > 0 and tools or nil,
      tool_choice = isLastStep and "none" or nil,
      stream = ctx.stream and true or false,
    }, { timeout = ctx.timeout, onDelta = onDelta })

    if not result then
      message.parts[#message.parts + 1] = { type = "step-finish", reason = "error" }
      message.time.completed = os.time()
      message.error = err
      ctx.on({ type = "error", message = err })
      return message, err
    end

    if not textPart and result.content ~= "" then
      session.addText(message, result.content)
      ctx.on({ type = "text", delta = result.content })
    end
    if result.reasoning ~= "" then
      session.addReasoning(message, result.reasoning)
      ctx.on({ type = "reasoning", text = result.reasoning })
    end

    runTools(ctx, message, result.toolCalls, history)
    session.finishStep(message, result.finish, result.usage)
    ctx.on({ type = "step_end", message = message })

    if options.onStepEnd then
      options.onStepEnd(message)
    end
    if ctx.aborted() then
      ctx.on({ type = "aborted" })
      return message, "aborted"
    end
    if ctx.blocked then
      return message
    end
    if result.finish ~= "tool-calls" then
      break
    end
  end

  return session.latestAssistantMessage(current)
end

--- Ask the small model for a session title. Failures are silent.
function M.title(ctx, text)
  if not ctx.smallModel or not text or #text < 4 then
    return nil
  end
  local result = llm.chat({
    model = ctx.smallModel,
    messages = {
      { role = "system", content = prompt.TITLE },
      { role = "user", content = text },
    },
    generation = { maxTokens = 24 },
  }, { timeout = 20 })
  if not result or not result.content then
    return nil
  end
  return util.trim(result.content:gsub("[\"'`]", ""))
end

-- Compaction
--
-- Every turn resends the whole conversation, so a long session eventually asks
-- for more than a ComputerCraft computer can hold in one request. Compaction
-- replaces the older messages with a summary written by the small model, which
-- is what keeps a session usable past a few dozen turns.

--- Roughly how many bytes the conversation occupies.
--
-- An estimate is enough to decide when to compact, and this is cheap: it adds up
-- strings that are already in memory. Encoding every message to JSON on every
-- step would cost more than the compaction it is trying to avoid.
local function conversationBytes(current)
  local total = 0
  for _, message in ipairs(current.messages or {}) do
    -- Room for the envelope: role, ids, timestamps, usage.
    total = total + 96
    for _, part in ipairs(message.parts or {}) do
      if type(part.text) == "string" then
        total = total + #part.text
      elseif part.type == "tool" then
        local state = part.state or {}
        total = total + 96
        for _, key in ipairs({ "output", "error" }) do
          if type(state[key]) == "string" then
            total = total + #state[key]
          end
        end
      end
    end
  end
  return total
end

--- The first message of the conversation that must be kept.
--
-- Compaction drops messages from the front, and the newest user and assistant
-- messages are what tell the loop whether the turn is finished
-- (`session.isTurnComplete`), so the cut has to be in front of both.
local function keepFromIndex(current)
  local latestUser, latestAssistant
  for index = #current.messages, 1, -1 do
    if not latestUser and current.messages[index].role == "user" then
      latestUser = index
    elseif not latestAssistant and current.messages[index].role == "assistant" then
      latestAssistant = index
    end
  end
  local first = latestUser or latestAssistant
  if latestUser and latestAssistant then
    first = math.min(latestUser, latestAssistant)
  end
  return first
end

--- Replace the older part of the conversation with a one-message summary.
--
-- Returns the summary, or nil when there was nothing to do: the conversation
-- still fits, compaction is switched off, there is no small model to write the
-- summary, or the summary request failed. A failure leaves the conversation
-- exactly as it was, so the next request fails with the provider's own size
-- error rather than a silently truncated history.
function M.compact(ctx)
  local settings = ctx.config.compaction or {}
  if settings.auto == false or not ctx.smallModel then
    return nil
  end
  local limit = (ctx.model and ctx.model.limit and ctx.model.limit.context)
    or provider.DEFAULT_LIMIT.context
  local reserved = settings.reserved or config.DEFAULTS.compaction.reserved
  if conversationBytes(ctx.session) + reserved < limit then
    return nil
  end

  local current = ctx.session
  local cut = keepFromIndex(current)
  if not cut or cut < 2 then
    -- Nothing older than the current turn: there is no history to summarise, and
    -- dropping the turn itself would lose the question.
    return nil
  end

  local older = {}
  for index = 1, cut - 1 do
    older[#older + 1] = current.messages[index]
  end
  local transcript = json.encode(M.lower({ messages = older }, nil, nil), "  ")

  local result, err = llm.chat({
    model = ctx.smallModel,
    messages = {
      { role = "system", content = prompt.COMPACTION },
      { role = "user", content = transcript },
    },
    generation = { maxTokens = M.COMPACT_MAX_TOKENS },
  }, { timeout = 30 })
  if not result or not result.content or util.trim(result.content) == "" then
    ctx.on({ type = "error", message = "could not compact the conversation: " .. tostring(err or "the model said nothing") })
    return nil
  end

  for index = #older, 1, -1 do
    table.remove(current.messages, index)
  end
  table.insert(current.messages, 1, {
    id = util.id("msg"),
    role = "user",
    time = { created = os.time() },
    summary = true,
    parts = { { type = "text", text = "Summary of the conversation so far:\n\n" .. util.trim(result.content) } },
  })
  return result.content
end

return M

end

-- init.lua
__sources["cli"] = function(...)
do end
-- opencode for ComputerCraft: the entry point.
--
-- Two ways to use it:
--
--   opencode                     interactive, on a monitor if one is attached
--   opencode "list the programs" one turn, print the answer, exit
--   opencode run "..."           the same, spelled out
--
-- Everything below is presentation: argument parsing, the REPL, and rendering the
-- agent's events onto a screen. The work itself is in src/agent.lua.

--- Locate the library relative to this program, so the modular checkout and the
--- single-file bundle both work without editing `package.path` by hand.
local function bootstrap()
  local program = (shell and shell.getRunningProgram and shell.getRunningProgram()) or ""
  local directory = program:match("^(.*)/[^/]*$") or "."
  package.path = table.concat({
    directory .. "/?.lua",
    directory .. "/src/?.lua",
    directory .. "/src/?/init.lua",
    package.path,
  }, ";")
end

bootstrap()

local env = require("environment")
local config = require("config")
local provider = require("provider")
local session = require("session")
local agent = require("agent")
local registry = require("tool/registry")
local permission = require("permission")

local M = {}

M.AGENTS = { "build", "general", "plan", "explore" }

-- Colour is used sparingly: a monitor in a dark room does not need decoration, and
-- the light palette is a guess that is wrong about half the time anyway.
local WHITE, LIGHT_GRAY, YELLOW, RED = colors.white, colors.lightGray, colors.yellow, colors.red

--- Everything one invocation needs, rebuilt when /model or /agent changes it.
M.state = {}

local function out(monitor, text, colour)
  if not monitor then
    return
  end
  if colour then
    monitor.setTextColor(colour)
  end
  monitor.write(text)
  monitor.setTextColor(WHITE)
end

local function line(monitor, text, colour)
  out(monitor, text .. "\n", colour)
end

--- Shorten a tool's input to one line, for the activity log.
local function summarise(part)
  local input = part.state.input or {}
  for _, key in ipairs({ "filePath", "path", "pattern", "command", "url" }) do
    if type(input[key]) == "string" then
      local value = input[key]:gsub("\n", " ")
      if #value > 48 then
        value = value:sub(1, 45) .. "..."
      end
      return value
    end
  end
  for key, value in pairs(input) do
    if type(value) ~= "table" then
      return tostring(key) .. "=" .. tostring(value)
    end
  end
  return ""
end

--- Render the agent's events. This is the whole UI: one line per tool call, the
--- answer as it arrives, and a usage footer.
local function renderer(monitor)
  return function(event)
    if event.type == "text" then
      out(monitor, event.delta)
    elseif event.type == "reasoning" then
      line(monitor, "(reasoning) " .. event.text, LIGHT_GRAY)
    elseif event.type == "tool_start" then
      local part = event.part
      line(monitor, "  * " .. part.tool .. " " .. summarise(part), LIGHT_GRAY)
    elseif event.type == "tool_end" then
      local part = event.part
      if part.state.status == "error" then
        line(monitor, "    ! " .. tostring(part.state.error), RED)
      else
        -- A tool whose title is the thing the start line already named — read
        -- and webfetch, mostly — has nothing to add by repeating it.
        local detail = part.state.title or ""
        if detail ~= "" and detail ~= summarise(part) then
          line(monitor, "    " .. detail, LIGHT_GRAY)
        end
      end
    elseif event.type == "step_end" then
      local tokens = event.message.tokens
      if tokens and tokens.input and tokens.input > 0 then
        line(monitor, string.format("  (%d in, %d out)", tokens.input, tokens.output), LIGHT_GRAY)
      end
    elseif event.type == "compacted" then
      -- The conversation was summarised, so an answer may now rest on the
      -- summary. Saying so beats silently losing the detail.
      line(monitor, "(summarised the earlier conversation to fit the context window)", LIGHT_GRAY)
    elseif event.type == "error" then
      line(monitor, tostring(event.message), RED)
    elseif event.type == "aborted" then
      line(monitor, "(aborted)", YELLOW)
    end
  end
end

--- Resolve the configured model, returning nil plus the reason it cannot be used.
local function resolveModel(current)
  local resolved, err = provider.resolve(current.config, current.config.model)
  if not resolved then
    return nil, err
  end
  return resolved
end

--- Build the run context from the current state.
local function buildContext(monitor)
  local current = M.state
  return {
    session = current.session,
    config = current.config,
    model = current.model,
    smallModel = current.smallModel,
    agent = current.agent,
    root = current.root,
    cwd = current.cwd,
    permission = permission.ruleset(current.config.permission),
    enabled = current.enabled,
    monitor = monitor,
    stream = current.stream,
    on = renderer(monitor),
    -- ComputerCraft gives a program no way to be interrupted while it runs, so
    -- this never fires. It is here so the loop has one place to ask.
    aborted = function()
      return false
    end,
  }
end

-- Slash commands

local function banner(monitor, current)
  line(monitor, "opencode for ComputerCraft", LIGHT_GRAY)
  line(monitor, string.format("model: %s   agent: %s   dir: %s", current.config.model, current.agent, current.cwd), LIGHT_GRAY)
  line(monitor, "Type a question, or /help for commands.", LIGHT_GRAY)
end

local function help(monitor)
  line(monitor, "Commands:")
  line(monitor, "  /help           this list", LIGHT_GRAY)
  line(monitor, "  /model          show the current model", LIGHT_GRAY)
  line(monitor, "  /model <id>     switch to provider/model", LIGHT_GRAY)
  line(monitor, "  /models         models the config can reach", LIGHT_GRAY)
  line(monitor, "  /providers      the known providers and their keys", LIGHT_GRAY)
  line(monitor, "  /agent          show the current agent", LIGHT_GRAY)
  line(monitor, "  /agent <name>   switch agent (" .. table.concat(M.AGENTS, ", ") .. ")", LIGHT_GRAY)
  line(monitor, "  /tools          list the available tools", LIGHT_GRAY)
  line(monitor, "  /new            start a new session", LIGHT_GRAY)
  line(monitor, "  /save           save the session to disk", LIGHT_GRAY)
  line(monitor, "  /exit           quit", LIGHT_GRAY)
  line(monitor, "Anything else is sent to the model.", LIGHT_GRAY)
end

--- `/models` shows what the config can actually reach. A provider with no `models`
--- block cannot be listed, because nothing in the config says which model ids it
--- serves, so the hint points at the file rather than guessing.
local function listModels(monitor, current)
  local models = provider.availableModels(current.config)
  if #models == 0 then
    line(monitor, "No models are listed in the config.", YELLOW)
    line(monitor, 'Add one under "provider" in opencode.json:', LIGHT_GRAY)
    line(monitor, '  "provider": {"groq": {"models": {"llama-3.3-70b": {"name": "Llama 3.3 70B"}}}}', LIGHT_GRAY)
    return
  end
  for _, entry in ipairs(models) do
    local note = entry.available and "" or "  (no api key)"
    line(monitor, string.format("  %-36s %-16s%s", entry.id, entry.provider, note), entry.available and WHITE or LIGHT_GRAY)
  end
end

local function listProviders(monitor, current)
  local providers = provider.list(current.config)
  local ids = {}
  for id in pairs(providers) do
    ids[#ids + 1] = id
  end
  table.sort(ids)
  for _, id in ipairs(ids) do
    local entry = providers[id]
    local key = provider.apiKey(current.config, entry)
    local note = key and "" or "  (no api key)"
    line(monitor, string.format("  %-12s %-14s %s%s", id, entry.name or id, entry.base or "(no base url)", note),
      key and WHITE or LIGHT_GRAY)
  end
end

local function listTools(monitor, current)
  for _, tool in ipairs(registry.list(current.enabled)) do
    line(monitor, "  " .. tool.id)
  end
end

--- Give the session a generated name, once, just before it is saved.
--
-- The first question makes a far better title than "New session", but naming
-- costs a request, so it happens on save rather than on every turn. A failure
-- leaves the default title: a session with an unhelpful name is a minor
-- inconvenience, not a broken run, so nothing is reported.
local function nameSession(monitor)
  local current = M.state
  if current.config.title == false or current.session.title ~= session.DEFAULT_TITLE then
    return
  end
  local name = agent.title(buildContext(monitor), session.text(session.firstUserMessage(current.session)))
  if name and name ~= "" then
    current.session.title = name
  end
end

--- Write the session to disk, naming it first if it still has no name.
local function save(monitor)
  nameSession(monitor)
  local path, err = session.save(M.state.session)
  if path then
    line(monitor, "saved " .. path, LIGHT_GRAY)
  else
    line(monitor, "could not save: " .. tostring(err), RED)
  end
end

--- Handle a slash command. Returns false when the REPL should stop.
local function command(monitor, input)
  local current = M.state
  local verb, rest = input:match("^/(%S+)%s*(.*)$")
  if not verb then
    return true
  end
  rest = rest:gsub("^%s+", ""):gsub("%s+$", "")

  if verb == "exit" or verb == "quit" then
    return false
  elseif verb == "help" then
    help(monitor)
  elseif verb == "model" then
    if rest == "" then
      line(monitor, current.config.model)
    else
      local resolved, err = provider.resolve(current.config, rest)
      if not resolved then
        line(monitor, err, RED)
      else
        current.config.model = rest
        current.model = resolved
        line(monitor, "model: " .. rest)
      end
    end
  elseif verb == "models" then
    listModels(monitor, current)
  elseif verb == "providers" then
    listProviders(monitor, current)
  elseif verb == "agent" then
    if rest == "" then
      line(monitor, current.agent)
    else
      local known = false
      for _, name in ipairs(M.AGENTS) do
        known = known or name == rest
      end
      if not known then
        line(monitor, "Unknown agent '" .. rest .. "'. Try: " .. table.concat(M.AGENTS, ", "), RED)
      else
        current.agent = rest
        line(monitor, "agent: " .. rest)
      end
    end
  elseif verb == "tools" then
    listTools(monitor, current)
  elseif verb == "new" then
    current.session = session.new()
    line(monitor, "new session " .. current.session.id, LIGHT_GRAY)
  elseif verb == "save" then
    save(monitor)
  else
    line(monitor, "Unknown command /" .. verb .. ". Try /help.", RED)
  end
  return true
end

-- Turns

--- Run one user turn, printing the result. Returns the message, or nil plus the
--- reason the run stopped early.
local function turn(monitor, text)
  local current = M.state
  session.addUser(current.session, text)
  return agent.run(buildContext(monitor))
end

--- Report whatever ended the run other than a normal finish.
local function reportStop(monitor, message, reason)
  if reason == nil or reason == "aborted" then
    return
  end
  if message and message.error then
    return
  end
  line(monitor, tostring(reason), YELLOW)
end

local function prompt(monitor)
  monitor.setCursorBlink(true)
  local answer = monitor.readLine()
  monitor.setCursorBlink(false)
  return answer
end

local function finish(monitor)
  if M.state.autoSave then
    save(monitor)
  end
end

--- The interactive loop.
local function repl(monitor)
  banner(monitor, M.state)
  while true do
    line(monitor, "")
    out(monitor, "> ", LIGHT_GRAY)
    local input = prompt(monitor)
    if input == nil then
      return
    end
    input = input:gsub("^%s+", ""):gsub("%s+$", "")
    if input == "" then
      -- nothing typed; ask again
    elseif input:sub(1, 1) == "/" then
      if not command(monitor, input) then
        finish(monitor)
        return
      end
    elseif M.state.model == nil then
      line(monitor, "No usable model. Try /model, or fix the config.", RED)
    else
      reportStop(monitor, turn(monitor, input))
    end
  end
end

--- One turn and out, for `opencode "<question>"`.
local function once(monitor, text)
  if M.state.model == nil then
    line(monitor, M.state.error or "No model configured.", RED)
    return 1
  end
  local message, reason = turn(monitor, text)
  line(monitor, "")
  reportStop(monitor, message, reason)
  finish(monitor)
  -- A turn that ended in a provider or transport error is a failed run, and a
  -- caller watching the exit code should be able to tell.
  if not message or message.error or reason then
    return 1
  end
  return 0
end

-- Argument parsing

local function usage(monitor)
  line(monitor, "opencode for ComputerCraft")
  line(monitor, "")
  line(monitor, "  opencode                    interactive session", LIGHT_GRAY)
  line(monitor, "  opencode <question>         one turn, then exit", LIGHT_GRAY)
  line(monitor, "  opencode run <question>     the same, spelled out", LIGHT_GRAY)
  line(monitor, "")
  line(monitor, "Options:")
  line(monitor, "  --model <id>     provider/model to use", LIGHT_GRAY)
  line(monitor, "  --agent <name>   " .. table.concat(M.AGENTS, ", "), LIGHT_GRAY)
  line(monitor, "  --dir <path>     working directory (default: the shell's)", LIGHT_GRAY)
  line(monitor, "  --save           save the session when it ends", LIGHT_GRAY)
  line(monitor, "  --stream         ask the provider for a stream", LIGHT_GRAY)
  line(monitor, "  --help           this list", LIGHT_GRAY)
end

--- Split the program's arguments. `run` is accepted and ignored so the one-shot
--- form can be spelled out.
local function parse(argv)
  local options = { save = false, stream = false, help = false }
  local rest = {}
  local index = 1
  while index <= #argv do
    local item = argv[index]
    if item == "--model" or item == "--agent" or item == "--dir" then
      options[item:sub(3)] = argv[index + 1]
      index = index + 2
    elseif item == "--save" then
      options.save = true
      index = index + 1
    elseif item == "--stream" then
      options.stream = true
      index = index + 1
    elseif item == "--help" or item == "-h" then
      options.help = true
      index = index + 1
    elseif item == "run" and #rest == 0 then
      index = index + 1
    else
      rest[#rest + 1] = item
      index = index + 1
    end
  end
  options.question = table.concat(rest, " ")
  return options
end

--- Build the run state from parsed arguments. Split out so the REPL, one-shot
--- mode, and the test harness all start from the same place.
function M.setup(argv, monitor)
  local options = parse(argv or {})
  local cwd = options.dir and env.resolve(options.dir, env.cwd()) or env.cwd()

  local overrides = {}
  if options.model then
    overrides.model = options.model
  end

  local current = {
    config = config.load(cwd, overrides),
    cwd = cwd,
    root = cwd,
    agent = options.agent or "build",
    session = session.new(),
    monitor = monitor,
    autoSave = options.save,
    stream = options.stream,
    enabled = nil,
  }
  current.enabled = current.config.tools

  current.model, current.error = resolveModel(current)
  if current.model then
    local small = provider.resolve(current.config, current.config.small_model)
    -- Falling back to the main model beats refusing to name a session at all.
    current.smallModel = small or current.model
  end

  M.state = current
  return current, options
end

--- Program entry point. Returns the shell exit code.
function M.main(argv, monitor)
  monitor = monitor or env.terminal()
  if not monitor then
    return 1
  end

  local state, options = M.setup(argv, monitor)
  if options.help then
    usage(monitor)
    return 0
  end
  if state.model == nil and state.error then
    -- Not fatal in the REPL: /model can still fix it, and the message says what is
    -- wrong. In one-shot mode `once` reports it instead, so it is not said twice.
    if options.question == "" then
      line(monitor, state.error, YELLOW)
    end
  end

  if options.question ~= "" then
    return once(monitor, options.question)
  end
  repl(monitor)
  return 0
end

return M

end
-- Module loading.
--
-- This deliberately does not read `package.loaded` to decide whether a module is
-- loaded. ComputerCraft's `require` marks the module it is loading with a
-- light-userdata sentinel, so a "is it already there?" check sees the sentinel
-- and hands that back to the caller in place of the module. `require` does its
-- own caching, so there is nothing to check.
local __loading = {}

local function __require(name, ...)
  local source = __sources[name]
  if not source then
    error("opencode: '" .. tostring(name) .. "' is not part of this bundle", 0)
  end
  if __loading[name] then
    -- The modules require each other, but never while one of them is still
    -- running: `tool/registry` pulls its tools in from `load()`, which is only
    -- called once the registry itself is complete. If this fires, it is a real
    -- require cycle and there is no way to guess the intended order.
    error("opencode: '" .. name .. "' is required while it is still loading, which cannot be resolved", 0)
  end
  __loading[name] = true
  local ok, result = pcall(source, name, ...)
  __loading[name] = nil
  if not ok then
    error("opencode: '" .. name .. "' failed to load: " .. tostring(result), 0)
  end
  package.loaded[name] = result == nil and true or result
  return result
end

for name in pairs(__sources) do
  package.preload[name] = __require
end

-- Run. The return value is the shell's exit code, and ComputerCraft passes `arg`
-- in as a global, so `opencode <question>` works the same as it does for the
-- modular version.
return __require("cli").main(arg or {}, nil)
